export const GLOSSARY: GlossaryEntry[] = [
  { term: "Aborted gesture of appropriation", slug: "aborted-gesture-of-appropriation", concept: "originary-scene", gloss: "The gesture in the Originary Event that aborted appropriation of the central object of desire.", posts: 23, passages: [{ text: "The aborted gesture of appropriation, then, restores that fleeting condition of perfect information in a more sustainable form.", slug: "scenic-event-intelligence", title: "Scenic/Event Intelligence", source: "Substack" }, { text: "It is this aborted gesture of appropriation, designating the object, but no longer directed at appropriating it, that we postulate as the first sign.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The originary sign, the aborted gesture of appropriation, points to a center that is simultaneously a sheer \u201cthis\u201d (one of Wierzbicka\u2019s primes, incidentally), that is, the very thing that we are looking at right now, and a named object and agent, from which all other names, acts and intentions derive.", slug: "on-the-use-of-the-center-margin-model-to-displace-the-left-right-model", title: "On the Use of the Center-Margin Model to Displace the Left-Right Model", source: "GABlog" }], sources: [{ slug: "clr-535", title: "The New Origin of Language: (A Derridean Parenthesis)", source: "Chronicles" }, { slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }] },
  { term: "Absolute Imperative", slug: "absolute-imperative", gloss: "The Imperative to defer violent centralizing.", posts: 20, passages: [{ text: "The absolute imperative is to stand in the place of whomever is violently centralized, i.e., scapegoated.", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }, { text: "But that in turn means that the absolute imperative is translated into the command to raise the marginal imperative.", slug: "declarative-imaginary", title: "Declarative Imaginary", source: "GABlog" }, { text: "This absolute imperative is, over time, pared down to \u201cdon\u2019t break linguistic presence,\u201d and this entails bringing some repetition of the originary scene in to supplement the failing linguistic presence.", slug: "programming-power-and-declarative-culture", title: "Programming, Power and Declarative Culture", source: "GABlog" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }, { slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }] },
  { term: "Abstracting", slug: "abstracting", gloss: "3rd order Attentionality.", posts: 16, passages: [{ text: "If I keep returning to and abstracting from the center, I head towards the creation of requests to the center that are simultaneously their own answers.", slug: "the-discourse-of-the-center", title: "The Discourse of the Center", source: "GABlog" }, { text: "Rather than abstracting mass organization from social interaction, the observation of social interaction itself would have to become the source of models for technological transformation.", slug: "conditions-for-an-enduring-technostructural-civilization", title: "Conditions for an Enduring Technostructural Civilization", source: "GABlog" }, { text: "They will be the source of economic dynamism, abstracting themselves and everyone else ever more thoroughly, and generating new forms of technology out of all the newly possible configurations.", slug: "absolutist-economies-gablog", title: "Absolutist Economies", source: "GABlog" }], sources: [] },
  { term: "Abstraction", slug: "abstraction", gloss: "Any kind of linguistic (moral) reconfiguration that is delegated.", posts: 43, passages: [{ text: "By now, the forms of embedment defended against abstraction are the results of previous abstractions that have been re-embedded.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { text: "Abstraction creates new \u201celements,\u201d and therefore new relations between elements.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "The abstraction of the sovereign from rivalry provides a model of action free from resentment: regardless of the actual motives of actual sovereigns, to the extent that they are sovereign the absence of resentment can be imputed to them.", slug: "the-generativity-of-deferral", title: "The Generativity of Deferral", source: "GABlog" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }] },
  { term: "Aesthetics", slug: "aesthetics", gloss: "An oscillation between desire and deferral.", posts: 43, passages: [{ text: "Aesthetics is located on the originary scene, in the oscillation of the attention of the participants between the sign put forth by the other and the object.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }, { text: "This history commences once aesthetics is distinguished from ritual.", slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }, { text: "Aesthetics, then, also refuses degraded and decadent forms of sacrality, like the bizarre Christian heresies that have devolved into liberalism.", slug: "as-who-does-one-speak", title: "As Who Does One Speak?", source: "GABlog" }], sources: [{ slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }, { slug: "the-aesthetic-as-liminally-scenic", title: "The Aesthetic as Liminally Scenic", source: "GABlog" }] },
  { term: "Agency", slug: "agency", gloss: "One\u2019s ability to modulate an inherited frame [and construct Formal Objects] through Signing.", posts: 84, passages: [{ text: "Agency is located in some form of programming while the analog/screenic offers stupefaction.", slug: "programming-and-visuality-toward-inscipto-punctual-cultivation", title: "Programming and Visuality: Toward Inscipto-Punctual Cultivation", source: "Substack" }, { text: "But we will see that Lobo\u2019s focus on the individual organism as opposed to any collective agency is an important component of his critique of the originary hypothesis.", slug: "addressing-an-objection-to-the-originary-hypthesis", title: "Addressing an Objection to the Originary Hypthesis", source: "Substack" }, { text: "The agency of the center is constructed through the ongoing interaction between center and margins.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }], sources: [] },
  { term: "Art", slug: "art", gloss: "A practice of deritualization by exposing the preliminary practices of ritualization.", posts: 103, passages: [{ text: "The materials of art are the materials of other areas of life, which also use colors, shapes, surfaces, words, sounds, etc.", slug: "relevance", title: "Relevance", source: "GABlog" }, { text: "The scene of art is a supplement or direct replacement of the ritual scene, with the art object or happening at the center and the audience at the periphery.", slug: "puppets-and-probes", title: "Puppets and Probes", source: "GABlog" }, { text: "The separation of art from ritual coincides with the same disruption of sacral kingship that produces politics and the problem of the \u201ctyrant.\u201d It\u2019s therefore not surprising that central to the first works of art is the problem of the tyrant and usurpation of the center more generally.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }], sources: [{ slug: "the-aesthetic-as-liminally-scenic", title: "The Aesthetic as Liminally Scenic", source: "GABlog" }] },
  { term: "Attentional Space", slug: "attentional-space", gloss: "A space where attention is held jointly on a particular object.", posts: 8, passages: [{ text: "Referring to something implicates one in an attentional space: you\u2019re adding to the attentional \u201cload\u201d of something other have been, are, or might be talking about.", slug: "morality-and-reference", title: "Morality and Reference", source: "GABlog" }, { text: "The disciplinary space joins the attentional space and works on making it disciplinary by making the relation between subject and object, between those with the desires and resentments and the reality resistant to it, itself the real object of study.", slug: "order-and-repetition", title: "Order and Repetition", source: "GABlog" }, { text: "The ostensive sign, the attentional space it summons, can only be completed if supplemented by referring to what is missing in a way that would eventuate in someone supplying it.", slug: "assigning-for-interoperability", title: "Assigning for Interoperability", source: "Substack" }], sources: [] },
  { term: "Attentionality", slug: "attentionality", concept: "attentionality", gloss: "The sharing and mutual awareness of sharing a common line of attention on some object.", posts: 10, passages: [{ text: "This is the kind of question my essays on \u201cattentionality\u201d and \u201cmistakenness\u201d were trying to answer.", slug: "event-al-morality", title: "Event-al Morality", source: "GABlog" }, { text: "What are the new modes of attentionality; how are we seeing and giving ourselves to be seen (and heard and felt and imagined) in new ways?", slug: "selfy", title: "Selfy", source: "GABlog" }, { text: "I have argued previously for the priority of \u201cattentionality\u201d over \u201cintentionality\u201d\u2014attention must precede intention, and \u201cintention\u201d individualizes what is \u201cjoint\u201d in attention, making it more of a declarative than an ostensive concept.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }], sources: [{ slug: "ap1901-1901katz", title: "Attentionality and Originary Ethics: Upclining", source: "AP Journal" }], },
  { term: "Authority", slug: "authority", gloss: "The power to modulate a given frame or context people share, redirecting attention by revealing and naming.", posts: 221, passages: [{ text: "That is not how moral authority is claimed; that is how it is surrendered.", slug: "obama-s-symmetries", title: "Obama\u2019s Symmetries", source: "GABlog" }, { text: "Post-ritualistic patriarchal authority is established as a tributary of monarchical authority, which in turn models itself on the former.", slug: "fathers-and-sovereigns", title: "Fathers and Sovereigns", source: "GABlog" }, { text: "Institutional position and authority are essentially constitutive gestural elements, situating one person closer to the center or more \u201cvertically\u201d than another.", slug: "the-rights-of-the-anyown-2-the-idioms-of-the-anyown", title: "The Rights of the Anyown 2: The Idioms of the Anyown", source: "GABlog" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Awe", slug: "awe", gloss: "A feeling like the co-mingling of dread, veneration, and wonder, when one has an encounter with the originary ostensive, which all ostensives are layered over concentrically: As the force of emotion that underlies the ab.", posts: 9, passages: [], sources: [] },
  { term: "Axial Age", slug: "axial-age", gloss: "The conceptual overthrow of divine kingship: Post-sacrificial Imperative Exchange ensued the conceptual overthow of divine kingship, unto modern liberal hyper-ideologies.", posts: 39, passages: [{ text: "At the heart of the Axial Age are the antinomies of the juridical, which take the form of the possibility of an injustice beyond remedy within the justice system.", slug: "ve-ortexicality-post-axial-age-morality", title: "Ve/ortexicality: Post-Axial Age Morality", source: "Substack" }, { text: "My argument here is that the Axial Age is the ongoing testing and examination of this kind of hypothetical case which was, in fact, most closely realized in the cases of Socrates and Jesus.", slug: "the-pointman", title: "The Pointman", source: "Substack" }, { text: "The Axial Age acquisitions, then, restart history by creating centers outside of the imperial one.", slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }], sources: [{ slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }, { slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }] },
  { term: "Big Man", slug: "big-man", concept: "big-man", gloss: "The first person to usurp the Center.", posts: 127, passages: [{ text: "The Big Man is the beginning of history and of all our ethical and political dilemmas.", slug: "what-is-to-be-undone-1", title: "What is to be Undone?, 1", source: "GABlog" }, { text: "The Big Man is the Alpha, a term central to the socio-sexual hierarchy constitutive of androspheric thinking.", slug: "the-androsphere-or-the-return-of-the-big-man-who-never-really-left", title: "The Androsphere, or the Return of the Big Man (Who Never Really Left)", source: "GABlog" }, { text: "The Big Man is first of all the center of distribution: gifts come to him and he recycles them back out to the community.", slug: "the-grammar-of-technology-gablog", title: "The Grammar of Technology", source: "GABlog" }], sources: [], },
  { term: "Bureaucracy", slug: "bureaucracy", gloss: "To make sure something is done [properly] in accordance with a discipline\u2019s own frame/rules/guidelines.", posts: 38, passages: [{ text: "Bureaucracy is always called into being when those differences have resisted elimination, or when new, and even more egregious, differences emerge out of the wreckage of the first attempt at differencide.", slug: "toward-a-unified-field-theory-of-the-left", title: "Toward a Unified Field Theory of the Left", source: "GABlog" }, { text: "Bureaucracy is characterized by rules designed or, perhaps more often, \u201cevolved\u201d through settlements of specific cases, to \u201crationalize\u201d interactions and regularize the functions of the institution.", slug: "continuum-of-power", title: "Continuum of Power", source: "Substack" }, { text: "Discipline and disciplines are good; bureaucracy is, if not evil, then an evil.", slug: "dismantling-the-victimocracy", title: "Dismantling the Victimocracy", source: "GABlog" }], sources: [{ slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }] },
  { term: "Capital", slug: "capital", concept: "capital", gloss: "Represents power over the disciplines.", posts: 87, passages: [{ text: "Capital is so all-embracing and all penetrating that it\u2019s hard to imagine what it would mean to think outside of, or beyond it.", slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { text: "Capital is a distribution of power aimed at solving the succession problem by constraining the possibilities\u2014no ruler can rule against capital.", slug: "successful-succession", title: "Successful Succession", source: "GABlog" }, { text: "Capital is property that can be borrowed against and therefore generate more wealth than it contains itself\u2014but that\u2019s impossible if legal titles are not available, especially if much of this \u201cproperty\u201d is held not only extra-legally but illegally.", slug: "the-right-of-the-idiom-part-1", title: "The Right of the Idiom: Part 1", source: "GABlog" }], sources: [{ slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "power-and-capital", title: "Power and Capital", source: "GABlog" }] },
  { term: "Center", slug: "center", concept: "the-center", gloss: "That which occupies the locus of attention and possesses the significance of the peripheral sign emitters within a scene.", posts: 540, passages: [{ text: "The center is now whatever can be attended to\u2014defined, treated, assessed, categorized, manipulated\u2014by disciplinary metalanguages.", slug: "center-and-centrality", title: "Center and Centrality", source: "GABlog" }, { text: "The center is at the center of the totality, and yet, since the center does not belong to the totality (is not part of the totality), the totality has its center elsewhere.", slug: "anthropomorphics-the-use-of-a-center", title: "The Use of a Center", source: "Book" }, { text: "The center is what makes any mutual understanding (any joint attention) possible, so disclosure is aimed at interrupting concealment of the conditions of such understanding.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "GABlog" }], sources: [{ slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }, { slug: "clr-579", title: "The Centre", source: "Chronicles" }, { slug: "ga-as-the-thinking-of-the-center", title: "GA as the Thinking of the Center", source: "GABlog" }] },
  { term: "Centered Ordinality", slug: "centered-ordinality", gloss: "An order in which the articulation of power from the center through the ranks it establishes is rendered transparent and consistent.", posts: 46, passages: [{ text: "Enacting and speaking in centered ordinality is the only way back to the center.", slug: "language-paradoxed", title: "Language Paradoxed", source: "GABlog" }, { text: "The centered ordinality you are most directly embedded in is, in its turn, embedded in another centered ordinality of which you are more or less directly aware, which your immediate center wants you to be more or less cognizant of.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }, { text: "Centered ordinality accounts for hierarchically ordered and yet reciprocal social relations (the first must attend to the second, who is attending to the first, and so on), whether those manifested in consensually recognized pre-eminence in informal settings, or in complex and organized institutions.", slug: "language-the-deepest-and-most-reliable-tradition", title: "Language, the Deepest and Most Reliable Tradition", source: "GABlog" }], sources: [{ slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }, { slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Centeredness", slug: "centeredness", gloss: "The quality of being centered: Formally and Informally, the degree to which something commands attention, is the degree to which the thing in question possesses the quality of Centeredness.", posts: 12, passages: [], sources: [] },
  { term: "Centering", slug: "centering", gloss: "[Occupying a/the Center, and] attracting the attention of people [in order to direct their attention to another Center].", posts: 56, passages: [{ text: "The means of self-centering are distributed to all of us equipped with various devices (we might say \u201capps\u201d) for leveraging, mobilizing and activating those means to wind us up as proxies for various liberalizing raids.", slug: "anthropomorphics-post-sacrificial-centrality", title: "Post-Sacrificial Centrality", source: "Book" }, { text: "From my discussion of morality in \u201cFraud and Force,\u201d we could say that responsible parties should establish institutions that extract from a situation in which some violent centering is possible the facts of the situation and the mode and degree of responsibility of all involved, freed from the logic of the vendetta.", slug: "moral-ethical-governance", title: "Moral, Ethical Governance", source: "GABlog" }, { text: "There are intimations of centering in even the most violent trashing.", slug: "centerism-gablog", title: "Centerism", source: "GABlog" }], sources: [{ slug: "centering", title: "Centering", source: "GABlog" }] },
  { term: "Central Authority", slug: "central-authority", gloss: "The starting point for issued commands.", posts: 47, passages: [{ text: "The more money in the system, the more the central authority is likely to be marketized as well.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { text: "In each case, some kind of resentment towards central authority is involved, ultimately for not being central and authoritative enough, as proven by the fact that one can challenge, revise and circumvent it in these very ways.", slug: "some-further-inquiry-into-hlvm-gablog", title: "Some further inquiry into HLvM", source: "GABlog" }, { text: "There is, in any community, a central authority, the final source of imperatives; and yet those imperatives are only worthy of being followed if the central authority is in accord with the signifying center: to put I more precisely, if the imperatives issued by the central authority are the same as those issued by the signifying center.", slug: "anthropomorphics-the-center-and-imperative-authority", title: "The Center and Imperative Authority", source: "Book" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }, { slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }] },
  { term: "Central Imaginary", slug: "central-imaginary", gloss: "The Ostensive or \u201ctopic\u201d that grounds/justifies the sets of imperatives surrounding it, and further out broader discourse in constative or Declarative form.", posts: 8, passages: [{ text: "Once we have identified the central imaginary as the \u201ctopic\u201d of our conversation, we can start to seek out imperatives from the center.", slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }, { text: "This means we all have what we could call a \u201ccentral imaginary\u201d: a proto-narrative of the center as the agent that could meet our demands.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }], sources: [{ slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }, { slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Charismatic", slug: "charismatic", concept: "charisma", gloss: "Autocracy \u2013 Katz\u2019 model for Interrogative Imperative culture following the Post-Sacrificial.", posts: 9, passages: [{ text: "Charismatic disclosure is therefore \u201capocalyptic\u201d in the more common sense, insofar as it is always combustible, always raises hackles and induces shrieks.", slug: "a-kind-of-apocalyptic-politics", title: "A Kind of Apocalyptic Politics", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }] },
  { term: "Consciousness", slug: "consciousness", gloss: "Transcendence of the simple plane of imitation.", posts: 50, passages: [{ text: "First is to say that consciousness is only possible for soul or spirit.", slug: "reflections-on-reading-raymond-tallis-aping-mankind", title: "Reflections on reading Raymond Tallis, Aping Mankind", source: "GABlog" }, { text: "Human consciousness is a new awareness of others, as mediated by a sign.", slug: "salvation-from-the-east", title: "Salvation from the East", source: "GABlog" }, { text: "In evolutionary terms, consciousness is a way for an organism to negotiate its environment.", slug: "thought-experiment", title: "Thought Experiment", source: "GABlog" }], sources: [] },
  { term: "Contemplation", slug: "contemplation", gloss: "Aesthetic oscillation.", posts: 8, passages: [{ text: "But the other is the esthetic contemplation of the linguistic sign, in which this paradoxical faith is not tested in practice but enacted, without resolution, in the imagination.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }] },
  { term: "Culture", slug: "culture", gloss: "The deferral of violence through representation.", posts: 275, passages: [{ text: "The proper use of declarative culture is to articulate all this, and engage others in its articulation.", slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }, { text: "In one sense, all of culture is originary, in the sense that all of culture can be traced back to the originary scene.", slug: "what-is-originary", title: "What is originary?", source: "GABlog" }, { text: "All of modern culture is a result of the misfit of models and aspirants, which is to say our fundamental mistakenness.", slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }], sources: [{ slug: "clr-648", title: "The Anthropological Idea of God\u201432 Years Later", source: "Chronicles" }] },
  { term: "Declarative", slug: "declarative", concept: "ostensive-imperative-declarative", gloss: "Speaking about something, detached from its physical presence.", posts: 240, passages: [{ text: "The declarative is born in terror of the imperative and, by extension, the ostensive, the latter of which it produces a virtual version of.", slug: "accessing-the-ostensive-within-the-declarative", title: "Accessing the Ostensive within the Declarative", source: "GABlog" }, { text: "The declarative was invented in the course of deferring the imperative, so it follows that one trajectory of the declarative is to imagine the abolition of the imperative.", slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }, { text: "The declarative is a kind of proposed bet that something we could recognize as the restored ostensive is out there, somewhere, and at least potentially available, if certain ostensive-imperative-ostensive conditions were to be fulfilled.", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }], sources: [{ slug: "on-the-proper-use-of-the-declarative-sentence", title: "On the Proper Use of the Declarative Sentence", source: "GABlog" }, { slug: "more-on-the-proper-use-of-declarative-sentences", title: "More on the Proper Use of Declarative Sentences", source: "GABlog" }, { slug: "the-declarative-order-and-inquiry", title: "The Declarative Order and Inquiry", source: "GABlog" }] },
  { term: "Declarative Culture", slug: "declarative-culture", gloss: "The culture where everything has to be explained in propositional (Declarative) statements.", posts: 29, passages: [{ text: "The proper use of declarative culture is to articulate all this, and engage others in its articulation.", slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }, { text: "We are completely within \u2018declarative culture\u201d here, and declarative culture is predicated on the banishment of imperatives and ostensives that don\u2019t \u201cfollow\u201d from declaratives.", slug: "declarative-culture-and-imperium-in-imperio-gablog", title: "Declarative Culture and Imperium in Imperio", source: "GABlog" }, { text: "Declarative culture promises us we will only have to obey one imperative: the imperative of reality.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }], sources: [{ slug: "declarative-culture-properly-understood-gablog", title: "Declarative Culture, Properly Understood", source: "GABlog" }] },
  { term: "Desacralization", slug: "desacralization", gloss: "The process of substitution of sacrality: The scientific will always seek to break a category down through substitution, which is invariably atomization. The scientific does not like that something could be irreducible.", posts: 14, passages: [{ text: "Secularization and desacralization is ultimately de-ritualization.", slug: "some-paradoxes", title: "Some Paradoxes", source: "GABlog" }, { text: "A broader desacralization is necessary before \u201cart\u201d can take on some kind of independence relative to the sacred, but until that point aesthetic considerations would be critical to representations of the sacred.", slug: "anthropomorphics-the-aesthetics-of-the-center", title: "The Aesthetics of the Center", source: "Book" }, { text: "Here is where the not reactionary, not even conservative, but well armored, resistance to the corrosions of desacralization are to be found(ed).", slug: "breakdown", title: "Breakdown", source: "Substack" }], sources: [] },
  { term: "Description", slug: "description", gloss: "Completed substitution: Description is a way to bring something that is not physically present unto the Scene as an object, so it can be treated as if it is physically present on the Scene.", posts: 66, passages: [{ text: "I think this description is accurate and the social transformation in itself beneficial, but, as it stands, massively forgetful.", slug: "liberal-ga-reactionary-ga", title: "Liberal GA, Reactionary GA", source: "GABlog" }, { text: "We can then ask which description is better\u2014people talking to each other as \u201cequal\u201d or people talking to each other as engaged in fine tuning and testing the direction each wants to lead the other.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "The implication of my description is that language is ordinarily invisible\u2014we don\u2019t notice ourselves speaking, we don\u2019t think of ourselves as adding one word to another as we speak, much less as making sounds that we could \u201clisten\u201d to by bracketing their meanings.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }], sources: [] },
  { term: "Desire", slug: "desire", concept: "desire", gloss: "An appetite for something generated by social prohibition.", posts: 310, passages: [{ text: "Desire is ultimately concerned, after all, not with appearance but with substance, appearance being only a means to an end.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Desire is generally understood in distinction from need, and in that way its specifically human quality is brought out\u2014desire implicates us in the other, which for mimetic theory means those we imitate or, more broadly, are bound to through a web of models.", slug: "demand-and-the-grammar-of-desire", title: "Demand and the Grammar of Desire", source: "Substack" }, { text: "We can certainly attribute to mimetic desire the \u201ccause\u201d for a particular act, but mimetic desire is always mediated through language.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }], },
  { term: "Disciplinarity", slug: "disciplinarity", concept: "disciplinarity", gloss: "The sharing of attention on some object.", posts: 20, passages: [{ text: "The political purpose of my study of disciplinarity is to get at the discursive roots, the roots in a habit of thinking, of \u201cpolitical philosophy,\u201d in all its forms, including the most everyday, \u201cpopular\u201d ones.", slug: "prolegomena-to-the-study-of-the-origins-of-the-disciplines-gablog", title: "Prolegomena to the Study of the Origins of the Disciplines", source: "GABlog" }, { text: "In the most basic sense, there is nothing but disciplinarity: disciplinarity is coextensive with the human: the originary scene was a discipline, even if that cannot be recognized until a critical mass of overlapping disciplines has emerged.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "The mode of exchange with the center of disciplinarity is that of data security, which includes the creation and archiving of knowledge that would, say, both inform a speech regime organized around a robust enforcement of laws against slander, libel and defamation while remaining invulnerable to that regime.", slug: "disciplinarity-and-the-center", title: "Disciplinarity and the Center", source: "Substack" }], sources: [] },
  { term: "Disciplinary Space", slug: "disciplinary-space", gloss: "A space of shared attention that turns the object it\u2019s studying into new signs.", posts: 99, passages: [{ text: "The disciplinary space is where we argue over these questions and construct such a center, and you have a disciplinary space when enough of these decisions have been made so that those within the discipline can readily generate new questions while those outside of the discipline would essentially be guessing if they tried.", slug: "disciplining-disciplines", title: "Disciplining Disciplines", source: "GABlog" }, { text: "The disciplinary space is an engine of differentiations, turning the object into a generator of new signs.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "Language learning is lifelong\u2014entering a new disciplinary space is learning a new language.", slug: "center-and-centrality", title: "Center and Centrality", source: "GABlog" }], sources: [] },
  { term: "Embedment", slug: "embedment", gloss: "[Situations/participation/belonging] in a communal and ritual [context/community].", posts: 10, passages: [{ text: "By now, the forms of embedment defended against abstraction are the results of previous abstractions that have been re-embedded.", slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }] },
  { term: "Esthetic", slug: "esthetic", gloss: "A form of experience in which a representational Sign is perceived as a necessary constituent of its imaginary referent: An oscillatory movement of the subject\u2019s attention between the sign and the referent.", posts: 48, passages: [{ text: "The esthetic is thereby reabsorbed back into ritual and elicits the millennia long suppressed producer\u2019s desire of all the people.", slug: "participation", title: "Participation", source: "GABlog" }, { text: "The satiric dimension within the esthetic is this moment of the scene at its most scenic, where we have what Gans once referred to as the \u201cfearful symmetry\u201d where each is at once potential victim and potential attacker, threatening and vulnerable simultaneously.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "Yet no student of painting or sculpture considers the pictorial or plastic components of artworks as in themselves devoid of esthetic interest, apprehended and integrated by means of a formal \u201ccompetence\u201d to which the esthetic is irrelevant.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "clr-260", title: "Originary and/or Kantian Esthetics I", source: "Chronicles" }, { slug: "clr-577", title: "Institutional Representation: The Esthetic II", source: "Chronicles" }] },
  { term: "Ethics", slug: "ethics", gloss: "Formal practices which are particular to a Disciplinary Space: Ethics involves the exchanging of ostensives, and the conversion of shared attention into collective intentionality.", posts: 84, passages: [{ text: "If ethics is centered upon some good to be obtained, morality defers another kind of centering\u2014the violent centering involved in sacrificial practices.", slug: "crowding-out-the-political-gablog", title: "Crowding Out the Political", source: "GABlog" }, { text: "Disciplines stay alive to the extent that the tension between value and ethics is re-established, through the creation of various forms of \u201c skunkworks \u201d within disciplines.", slug: "sovereignty-and-standardization", title: "Sovereignty and Standardization", source: "GABlog" }, { text: "While it doesn\u2019t quite prove anything, doesn\u2019t the fact that so many millions of people can be recruited into an increasingly apocalyptic leftism that in many cases at least cuts against individual economic self-interests suggest that for many, if not most, utilitarian ethics are extremely unsatisfying?", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }], sources: [{ slug: "ap1901-1901katz", title: "Attentionality and Originary Ethics: Upclining", source: "AP Journal" }, { slug: "ap1601-1601katz", title: "Originary Mistakenness, Defilement and Modernity", source: "AP Journal" }] },
  { term: "Event", slug: "event", concept: "event", gloss: "The new inscription that re-inscribes all the existing ones.", posts: 272, passages: [{ text: "An event is represented, and an event \u201cbehind\u201d that event: what\u2019s happening is shadowed by what is \u201creally\u201d happening.", slug: "anthropomorphics-declarative-order-and-the-center", title: "Declarative Order and the Center", source: "Book" }, { text: "So, the end of one event is identified as the beginning of another and the middle of a third event\u2014all within the same space.", slug: "hypothesis-practice-vs-narrative-the-iterative-center-gablog", title: "Hypothesis/Practice Vs. Narrative: The Iterative Center", source: "GABlog" }, { text: "The act of participation in this event is conscious in a way no animal action can be, because its conscious nature is inherent in the sign that is shared with the other members of the group.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }] },
  { term: "Exemplary Victim", slug: "exemplary-victim", gloss: "The victim of violence by the occupant of the Center.", posts: 11, passages: [{ text: "The exemplary victim is the one whose path we could follow as a means of salvation while always falling infinitely short of the example.", slug: "urbanomics", title: "Urbanomics", source: "GABlog" }, { text: "The exemplary victim is constitutive of our language and narratives, which is why it needs to be \u201cunwritten.\u201d The whole range of exemplary victims produced across the political spectrum constitutes our \u201calphabet\u201d (or, perhaps, \u201cmeme factory\u201d).", slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { text: "A large part of the power of models figuring an \u201cexemplary victim\u201d is precisely the plausibility and richness of the events they are drawn from, with Jesus on the cross, or Socrates sitting with his students waiting to drink his hemlock among the most obvious examples.", slug: "the-model-of-data", title: "The Model of Data", source: "GABlog" }], sources: [{ slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { slug: "dialectics", title: "Dialectics", source: "GABlog" }] },
  { term: "Explanation", slug: "explanation", gloss: "Making something comprehensible and coherent within a governing paradigm: To explain something is to make it understandable within the paradigm you\u2019re working with.", posts: 67, passages: [{ text: "And the libertarian explanation is\u2026 well, other than some vague references to our having forgotten our principles, it doesn\u2019t seem to me they really have one\u2014which would be why someone like Ron Paul exceeds even the most fevered Leftists in his conspiracy-mongering.", slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }, { text: "It seems to me that the best explanation is the alliance of the new, vulnerable, but potentially revolutionary market order with the absolutist state\u2014the imperial state, in other words, which is really nothing more than a permanently asymmetrical gift relationship (is there anything more \u201cgiven\u201d for us today than the state?).", slug: "the-terror-of-the-given", title: "The Terror of the Given", source: "GABlog" }, { text: "\u201cExplains\u201d lets us know more implicitly that an explanation is coming.", slug: "writing-pedagogy-katz", title: "From Novice to Apprentice: A Pedagogy of \"Academic Discourse\" (Adam Katz)", source: "Essay" }], sources: [] },
  { term: "Firstness", slug: "firstness", concept: "firstness", gloss: "The bringing of some new object to the group\u2019s attention / leading of a shared frame, articulated as asymmetry between speaker and listener in a speech situation — the one who brings something to the scene first takes on the risk and authority of priority.", posts: 55, passages: [{ text: "Maybe that will happen, if firstness is ever restored through a generalized immunity to the victimary.", slug: "the-androsphere-or-the-return-of-the-big-man-who-never-really-left", title: "The Androsphere, or the Return of the Big Man (Who Never Really Left)", source: "GABlog" }, { text: "A reliable indicator of firstness is the ability to revise previous assessments and assignments and to formalize present fitness.", slug: "mimetic-theory-and-high-low-v-the-middle", title: "Mimetic Theory and High-Low v the Middle", source: "GABlog" }, { text: "Second, though, as I suggested earlier, Jewish firstness is represented by a willingness to endure historical contingency, adhere to the moral law (even if no one else does), and ask for no recognition or \u201cproof\u201d of election.", slug: "anti-semitism", title: "Anti-Semitism", source: "GABlog" }], sources: [{ slug: "clr-606", title: "Sovereignty and Firstness", source: "Chronicles" }, { slug: "clr-451", title: "Reciprocity and Firstness", source: "Chronicles" }, { slug: "clr-496", title: "Religion and Firstness", source: "Chronicles" }] },
  { term: "Frame", slug: "frame", gloss: "A received/inherited historical configuration.", posts: 167, passages: [{ text: "If your frame is wrong, that\u2019s the only way you\u2019ll ever find out anyway.", slug: "within-language", title: "Within Language", source: "GABlog" }, { text: "To frame is to rule, and to target ways to enhance discipline is to frame.", slug: "frame-symmetry-equality", title: "Frame, Symmetry, Equality", source: "GABlog" }, { text: "What makes it that kind of frame is the practice that initiated it, and the way it draws in the elements and means from the whole.", slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }], sources: [] },
  { term: "Framing", slug: "framing", gloss: "Imposing a Frame on a Scene.", posts: 82, passages: [{ text: "Everyone must speak for the same amount of time?), the deliberative process is impaired, and if that framing is encouraged, it will impair the process beyond repair.", slug: "equality-and-morality-gablog", title: "Equality and Morality", source: "GABlog" }, { text: "In other words, power judges us in terms of \u201cequality\u201d or \u201cduty.\u201d The best framing is the one that unites power and accountability, that gives everyone the power to do what they are obliged to do\u2014in other words, absolutist framing.", slug: "sovereign-resentments", title: "Sovereign Resentments", source: "GABlog" }, { text: "Every one of us does know things about our respective milieus that no one else does, even if it may sometimes be the case that the proper questioning or framing is required to elicit such knowledge.", slug: "mimesis-center-auto-immunology", title: "Mimesis, the Center and Auto-Immunology: A Review of Psychopolitical Anaphylaxis", source: "Essay" }], sources: [] },
  { term: "Free will", slug: "free-will", gloss: "The ability to receive meaning and continue the linguistic frame through signing.", posts: 14, passages: [{ text: "On the other hand, consciousness and free will are completely anomalous in our universe.", slug: "further-reflections-consciousness-free-will", title: "Further Reflections, Consciousness & Free Will", source: "GABlog" }, { text: "Saying that human consciousness and free will are a function of our unique cultural/social \u201cnature\u201d may well be true, but it doesn\u2019t seem to answer the philosophical problem of how exactly this is possible.", slug: "reflections-on-reading-raymond-tallis-aping-mankind", title: "Reflections on reading Raymond Tallis, Aping Mankind", source: "GABlog" }, { text: "But this is not an act of existential free will on the part of each member of the new community.", slug: "anthropomorphics-origin-and-hypothesis", title: "Origin and Hypothesis", source: "Book" }], sources: [] },
  { term: "Freedom", slug: "freedom", gloss: "[The ability to formally construct objects of shared attention].", posts: 183, passages: [{ text: "The notion that equality and freedom are competing values is false to the core.", slug: "the-mistake-of-liberal-democracy", title: "The Mistake of Liberal Democracy", source: "GABlog" }, { text: "The elemental form of freedom is that of the discipline: a shared, inviolate and inexhaustible locus of attention.", slug: "the-right-of-the-idiom-2", title: "The Right of the Idiom, 2", source: "GABlog" }, { text: "If the choice between freedom and coercion is thus treated as a matter of expediency, freedom is bound to be sacrificed in almost every instance.", slug: "common-sense", title: "Common Sense", source: "GABlog" }], sources: [{ slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }, { slug: "clr-348", title: "The Four Freedoms", source: "Chronicles" }] },
  { term: "Grammatical Stack", slug: "grammatical-stack", gloss: "The articulation of Ostensive-Imperative-Interrogative-Declarative.", posts: 8, passages: [{ text: "To input the miraculous to the grammatical stack is to hypothesize wildly from the slightest sample.", slug: "the-algorithm-as-originary-stack", title: "The Algorithm as Originary Stack", source: "Substack" }, { text: "This involves ordering what we might call the \u201cgrammatical stack\u201d: the articulation of ostensive-imperative-interrogative-declarative.", slug: "conversivity", title: "Conversivity", source: "GABlog" }, { text: "Full exploitation or \u201coptimization\u201d of the grammatical stack would lead us to ask what would be the inappropriate ostensive that initiates the technological move and what would be the inappropriate technologized imperative that integrates technology into the declarative, which is to say, juridical and disciplinary, order.", slug: "the-grammar-of-technology-substack", title: "The Grammar of Technology", source: "Substack" }], sources: [{ slug: "conversivity", title: "Conversivity", source: "GABlog" }, { slug: "deriving-the-sample-to-its-source", title: "Deriving the Sample to its Source", source: "GABlog" }] },
  { term: "Identity", slug: "identity", gloss: "Delegation of power from the Central Authority over which part of the social order to govern: Identites are delegations of power to a group based on which part of the social order they are to govern and have responsibility for.", posts: 87, passages: [{ text: "If the difference between the two is reduced to the infinitesimal, the two will be changing positions, so your identity is simultaneously that of a learner as well as teacher.", slug: "as-who-does-one-speak", title: "As Who Does One Speak?", source: "GABlog" }, { text: "Insofar as we have a new center, that center wants to be more central: if we have a center we are using the same sign, and its identity is affirmed in the self-reference that situates one scene generated by the sign in a history of scenes with an origin that is continually marked.", slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }, { text: "But we can\u2019t do without sovereignty\u2014it meets some very definite human needs, and is, in fact, what people usually mean when they speak about \u201chuman nature.\u201d Sovereignty provides identity, which is first of all self-sovereignty, and, again, is inimical to freedom, as identity is just another set of shackles.", slug: "the-political-economy-of-freedom-and-sovereignty", title: "The Political Economy of Freedom and Sovereignty", source: "GABlog" }], sources: [{ slug: "identities", title: "Identities", source: "GABlog" }] },
  { term: "Imperative", slug: "imperative", concept: "ostensive-imperative-declarative", gloss: "A command derived from an Ostensive.", posts: 354, passages: [{ text: "The imperative is dependent on extra-linguistic real time in a way the ostensive is not.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The imperative is a set of expectations: be ready for what will happen to the main opponent/watch what the president will do next/look for that oppositional leader\u2019s profile to be raised.", slug: "programming-power-and-declarative-culture", title: "Programming, Power and Declarative Culture", source: "GABlog" }, { text: "The imperative is a result of an \u201cinappropriate ostensive.\u201d One member of the community issues the ostensive sign in the absence of the object, and another member of the community then supplies the object.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }], sources: [] },
  { term: "Imperative Culture", slug: "imperative-culture", gloss: "Another word for Imperativity: Look at the \u2018Imperativity\u2019 entry.", posts: 8, passages: [{ text: "What emerges within this imperative culture is a continual attempt to reduce the difference between performance and effect.", slug: "anthropomorphics-the-center-and-the-declarative", title: "The Center and the Declarative", source: "Book" }, { text: "In his analysis of imperative culture, Gans notes that the memory of the sacred object must conceive of that object as a sacred being that exists above and beyond the concrete manifestations it may take on.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }], sources: [{ slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }] },
  { term: "Imperative Exchange", slug: "imperative-exchange", gloss: "Acting in reciprocation with a center.", posts: 51, passages: [{ text: "The imperative exchange is replaced by a declarative culture in which the voice issuing the absolute imperative is always in dialogue with you to the extent that you defer the immediate imperatives to sacrifice either the target of your resentment or some proxy.", slug: "anthropomorphics-and-reaction", title: "Anthropomorphics and Reaction", source: "GABlog" }, { text: "The imperative exchange is embedded in a sacrificial economy: the subject demands more and more of God, as each form of salvation brings another form into view, and so God correspondingly demands more in return: in the end, the most treasured possession, i.e., your first born.", slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }, { text: "Imperative exchange is ancestor worship, and the absolute imperative embedded in I AM THAT I AM is to suspend ancestor worship and remember the originary scene\u2014that is, remember that it is the participation of all in creating reciprocity that generated the sign, not the other way around.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }] },
  { term: "Imperative Gap", slug: "imperative-gap", gloss: "The gap between the command issued and command obeyed: No order can be obeyed without a minimum of discretion being exercised, where the practice of commanding is about minimizing that gap.", posts: 27, passages: [{ text: "The work of closing the imperative gap is conducted in \u201cdisciplinary spaces,\u201d which are retrievals of the originary scene/event.", slug: "scale", title: "Scale", source: "Substack" }, { text: "Now, I can say that the imperative gap is closed to the extent that each of us contributes to singularized succession in perpetuity.", slug: "the-sufficiency-of-singularized-succession-in-perpetuity", title: "The Sufficiency of Singularized Succession in Perpetuity", source: "Substack" }, { text: "One\u2019s operationalization of the imperative gap is not an individual matter but derivative of one\u2019s position within the stack of scenes\u2014you can only start with the commands it is within your power to work with, and with whatever clarity the chain of imperatives they issue from is inscribed upon those aimed at you.", slug: "the-problem-of-obedience-revisited", title: "The Problem of Obedience, Revisited", source: "Substack" }], sources: [{ slug: "the-imperative-of-the-occupant-of-the-center", title: "The Imperative of the Occupant of the Center", source: "GABlog" }, { slug: "the-model-of-data", title: "The Model of Data", source: "GABlog" }] },
  { term: "Imperative of the Center", slug: "imperative-of-the-center", gloss: "To construct an iterable scene around an object.", posts: 17, passages: [{ text: "The problem of access to the imperative of the center is the problem of institution building, of data security and scenic design practices.", slug: "muffled-transmission-from-the-center-substack", title: "Muffled Transmission from the Center", source: "Substack" }, { text: "The parceling out of the imperative of the center means that a calculated strategy of betting against those most dedicated to the creation and transmission of practices of data security can not only break those lines of transmission but can turn those very practices against them.", slug: "modeling-thirdness-2", title: "Modeling Thirdness 2", source: "Substack" }, { text: "What I have been calling the partitioning and parceling out of the imperative of the center is not so much resisted as raveled up by creating knowledge of use to cases in stacked scenes that keeps pushing cases asymptotically to their self-abolishing limits.", slug: "the-same-sentence", title: "The Same Sentence", source: "Substack" }], sources: [{ slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }] },
  { term: "Imperativity", slug: "imperativity", gloss: "We are always trying to get word from the Center.", posts: 16, passages: [{ text: "Within interrogative imperativity, declaratives take on a far wider scope, that of converting possible (and impossible) imperative exchanges into a rule or constraint for deferring \u201canalogous\u201d imperative exchanges.", slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }, { text: "The para and the infra are the forms of imperativity, telling you what texts you must take as models, how to take them as models, how to use those models to work through some particular content or materials, and how to read texts as instantiations or modifications of those models.", slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }], sources: [{ slug: "the-architecture-of-the-center", title: "The Architecture of the Center", source: "GABlog" }, { slug: "imperativity", title: "Imperativity", source: "GABlog" }] },
  { term: "Individualism", slug: "individualism", gloss: "An elaboration of Collectivism.", posts: 17, passages: [{ text: "Don\u2019t look at me as a \u201c_____,\u201d the individual demands, look at me as\u2026 the other of \u201c_____.\u201d Individualism is a kind of negative gnostic theology.", slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { text: "There can never be enough democracy, freedom, individualism, peace, tolerance\u2014the concepts, unlike, say, sovereignty , are intrinsically open-ended and even infinite.", slug: "trump-s-process-of-inquiry-gablog", title: "Trump\u2019s Process of Inquiry", source: "GABlog" }, { text: "The most terrible consequences of liberal individualism come from the destruction of this assumption that all individuals, before all else, have their entire existence within the group.", slug: "distribution-from-the-center", title: "Distribution from the Center", source: "GABlog" }], sources: [] },
  { term: "Inquiry", slug: "inquiry", gloss: "The direction of attention to something attended from: Inquiry serves the social center by elaborating on discrepancies between sign and referent, thereby creating a sharper model for desire and its suspension.", posts: 273, passages: [{ text: "The inquiry into resentment, which is always the resentment of specific selves and others, is presumably part of culture, so this inquiry is itself part of the impossible attempt to represent and defer its own resentment.", slug: "resentment", title: "Resentment", source: "Substack" }, { text: "Inquiry is required to invent and regulate that technological mechanism, but once it is controlled by the feedback from measurable effects (the regularized relation between laughter and ratings) not only has the discipline of comedy been displaced but so, also, has the disciplinary inquiry into various forms of inducing laughter.", slug: "introduction-to-disciplinarity", title: "An Introduction to Disciplinarity (Adam Katz)", source: "Essay" }, { text: "The new pedagogy or mode of inquiry is then, partly explicitly and partly tacitly, integrated into the system of reciprocities.", slug: "sovereignty-difference-reciprocity-nature-value", title: "Sovereignty, Difference, Reciprocity, Nature, Value", source: "GABlog" }], sources: [] },
  { term: "Intentionality", slug: "intentionality", gloss: "Being able to direct your intention and knowing others have intention.", posts: 45, passages: [{ text: "Each layer of intentionality is a layer of deferral, and being able to say that maybe we can know or see allows us to add more layers.", slug: "toward-a-generative-logic-of-translation", title: "Toward a Generative Logic of Translation", source: "GABlog" }, { text: "Built into the notion of intentionality is some deep structure of the will; built into the notion of attention is something demanding attention and demanding you draw others\u2019 draw others\u2019 attention to, which involves configurating ourselves around something at the center.", slug: "the-center", title: "Lecture 4: The Center", source: "Essay" }, { text: "This presence is a collective, centered presence, and not the phenomenological self-presence (in which my intentionality is fully \u201cborne\u201d by my utterances) Derrida deconstructs, but a presence nevertheless.", slug: "the-name-of-god-technomedia-and-the-model-of-the-work-of-art", title: "The Name of God, Technomedia, and the Model of the Work of Art", source: "GABlog" }], sources: [] },
  { term: "Internal Scene of Representation", slug: "internal-scene-of-representation", gloss: "A kind of privatized space we can trace back to the sparagmos.", posts: 10, passages: [{ text: "One\u2019s internal scene of representation is the mental space within which we conceive the meaning of language, as when listening to another or reading a book.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "If we are to speak of an internal scene of representation, it must be composed as any scene\u2014by means of a sign of deferral of some appropriation that would, if attempted, destroy the scene.", slug: "psychogeography", title: "Psychogeography", source: "GABlog" }, { text: "This renunciation of the temptation to occupy internal scene of representation in rebellion against the tyrant in the name of some super-sovereign is what we can call \u201cdonating your resentment to the center.\u201d Media and technology are, as Marshall McLuhan noted, extensions of our senses and body.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "clr-531", title: "Paradox and the Sacred", source: "Chronicles" }] },
  { term: "Interrogative", slug: "interrogative", concept: "ostensive-imperative-declarative", gloss: "Inquiring into an Imperative: An Interrogative is when you ask into an Imperative, most importantly about what to do if an Imperative cannot be carried out/fulfilled. At this point you\u2019ve almost arrived at the Declarative mode of language.", posts: 80, passages: [{ text: "The interrogative is a prolonged imperative, which is to say an imperative that understands it may not be obeyed.", slug: "the-grammar-of-desire-and-resentment", title: "The Grammar of Desire and Resentment", source: "GABlog" }, { text: "Intervening between the imperative and the declarative is the interrogative; an interrogative is a softened imperative, which is to say, an imperative coming to recognize that it might not be fulfilled, and therefore transitioning from a command to do something to a demand for information regarding the possibility of doing it.", slug: "more-on-the-proper-use-of-declarative-sentences", title: "More on the Proper Use of Declarative Sentences", source: "GABlog" }, { text: "And then we become ostensive, imperative, interrogative and declarative signs of the center.", slug: "total-semiotics-or-exteriorizing-the-interiors", title: "Total Semiotics, or Exteriorizing the Interiors", source: "GABlog" }], sources: [] },
  { term: "Justice", slug: "justice", concept: "justice", gloss: "The idea that \u201ceveryone gets their due\u201d.", posts: 170, passages: [{ text: "The imperial institution of justice is therefore quite hostile to the heads and chiefs and the extended kinship relations they embody.", slug: "on-the-juridical-disciplinary-line", title: "On the Juridical/Disciplinary Line", source: "Substack" }, { text: "The assumption, though, is still that distribution comes from the center: justice is the distribution to each of his due, whatever that means and however it is to be determined.", slug: "distribution-from-the-center", title: "Distribution from the Center", source: "GABlog" }, { text: "That threshold itself is assessed with the specific networks in mind\u2014even vigilante justice is not necessarily excluded, as long as it doesn\u2019t pass the threshold beyond which there will be nothing but vigilante justice.", slug: "constrained-economies", title: "Constrained Economies", source: "GABlog" }], sources: [{ slug: "distribution-from-the-center", title: "Distribution from the Center", source: "GABlog" }, { slug: "clr-665", title: "Originary Reflections on the Present", source: "Chronicles" }] },
  { term: "Law", slug: "law", gloss: "Codified Moral History: Law is the codified Moral History of a group and and is thus an inherited frame for new people entering the group.", posts: 265, passages: [{ text: "The law is sufficient, that is, to continually generate hypotheses of the law\u2019s emergence and revised terms of its evolution, to maintain its divine sanction while reducing that sanction to maintaining the collegiality and accountability of its interpreters and the inexhaustibility of the shared text.", slug: "why-the-law-is-enough", title: "Why the Law is Enough", source: "GABlog" }, { text: "Generally honor cultures exist where the rule of law is weak.", slug: "up-from-victimhood", title: "Up from Victimhood", source: "GABlog" }, { text: "Needless to say, every law is enforced (or left unenforced) by someone.", slug: "sovereignty-heisenbergian-and-godelian", title: "Sovereignty Heisenbergian and Godelian", source: "GABlog" }], sources: [] },
  { term: "Legitimacy", slug: "legitimacy", gloss: "The intrinsic relation between Ostensive and Imperative.", posts: 99, passages: [{ text: "History, then, has exhausted itself in the antinomic agencies of contemporary liberalism, where the genuinely stripped bare human that can be the only source of legitimacy is nothing but sheer opposition to whatever norms make social functioning possible.", slug: "anthropomorphics-declarative-order-and-the-center", title: "Declarative Order and the Center", source: "Book" }, { text: "But what does the increasing or more intractable inequality have to do with the diminishing legitimacy function of the welfare state\u2014is it that the rich no longer have enough money to support it or the less able are no longer willing to accept the bribe (or have figured out that the bribe will continue even if legitimacy is denied)?", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "Success is only possible if you turn the infiltrators into your tools: speak always and only as if you will only obey the commands of legitimate leaders of legitimate institutions, and you are always simply pointing out that the rate of turnover in terms of legitimacy is accelerating and it can be rather difficult to keep up.", slug: "event-origin-center", title: "Event, Origin, Center (Adam Katz)", source: "Essay" }], sources: [{ slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Linguistic Presence", slug: "linguistic-presence", gloss: "The exchange of assurances that we continue to interact on the same Scene.", posts: 53, passages: [{ text: "Linguistic presence is not a \u201cchannel\u201d of communication, and al though for the higher linguistic forms, the channel analogy is an adequate approximation in most cases, it cannot help us to understand the origin of these forms.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The problem of linguistic presence is now posed in a new way.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }, { text: "If the other disobeys, linguistic presence is put in danger, and the moral thing to do is find some other way of maintaining it.", slug: "moral-thresholds", title: "Moral Thresholds", source: "GABlog" }], sources: [{ slug: "deriving-the-sample-to-its-source", title: "Deriving the Sample to its Source", source: "GABlog" }, { slug: "sampling-on-the-data-exchange", title: "Sampling on the Data Exchange", source: "Substack" }] },
  { term: "Linguistic Turn", slug: "linguistic-turn", gloss: "Rejection of finding legitimation of what we say in language, in some reality outside of language.", posts: 12, passages: [{ text: "The reason for the linguistic turn is that the metaphysical scene of humanism, predicated upon the metalinguistics of literacy, could no longer effectively defer violence.", slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }, { text: "Completing the linguistic turn is essential because the metalanguages of humanism and metaphysics obscure the forms of authority needed to ensure intelligent participation in institutions and hierarchical orders.", slug: "linguistic-turn-generative-literacy", title: "The Linguistic Turn and Generative Literacy (Adam Katz)", source: "Essay" }, { text: "The linguistic turn in Western thought in the 20 th century derives from this recognition, which was certainly aided by both the emergence of mass literacy and mass education, and by the emergence of new media that made it possible to place writing in a broader historical context.", slug: "within-language", title: "Within Language", source: "GABlog" }], sources: [{ slug: "gasc-2019-paper", title: "GASC 2019 Paper", source: "GABlog" }] },
  { term: "Literacy", slug: "literacy", gloss: "To be able to separate sign and cause.", posts: 116, passages: [{ text: "Literacy is crucially involved in the shift in the heroic narrative from the \u201cPromethean\u201d (and doomed) struggle against the center to the victim who exemplifies what we can now see as the unholy, even Satanic, violence of the imperial center.", slug: "toward-a-media-moral-synthesis", title: "Toward a Media-Moral Synthesis", source: "GABlog" }, { text: "For this purpose the metalanguage of literacy is deployed: relations between nominalizations deposit in the scene what might otherwise be looked for in the disciplinary scene of representation.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "The metalanguage of literacy is an intellectual or ideological bulwark to the state, while also providing the material for decentering power by appealing to transcendent models to which the sovereign must adhere.", slug: "linguistically-constructed-empires-within-empires", title: "Linguistically Constructed Empires within Empires", source: "GABlog" }], sources: [] },
  { term: "Logocentrism", slug: "logocentrism", gloss: "A metaphysics of presence which seeks to organize and ground illocutionary force with logic.", posts: 18, passages: [{ text: "If logocentrism is really phallocentrism, Eurocentrism, etc., then the critique of metaphysics is essentially volley in a partisan political battle, rather than an attempt to disclose a more originary presentation of human being than metaphysics allows.", slug: "idioms-of-inquiry-katz", title: "Another Version of \"Idioms of Inquiry\" Despite the Changed Title (Adam Katz)", source: "Essay" }, { text: "The logocentrism Derrida associated with Western metaphysical modes of thinking, along with all of its distinctions between rational and irrational, civilized and barbaric, and so on, can indeed be predicated upon modes of thinking produced by writing.", slug: "originary-grammar-and-post-sacrificial-semiotic-agency", title: "Originary Grammar and Post-Sacrificial Semiotic Agency", source: "GABlog" }, { text: "That logocentrism, that we see in concepts that construct phony simulations of battles between familiar opponents, is what is to be targeted most persistently.", slug: "media-as-scene-gablog", title: "Media as Scene", source: "GABlog" }], sources: [] },
  { term: "Love", slug: "love", gloss: "The transcendence of Resentment: The protection of the object of your desire from the violence incited by your own desire for it.", posts: 120, passages: [{ text: "In other words, what converts desire into love is that the object breaks out of the vicious circle of desire by giving promise of continual mystery and by making the desirer such an object him or her self.", slug: "rendering-is-the-stay-of-frenzy-ou-ga-po", title: "Rendering is the Stay of Frenzy: Ou-GA-po", source: "GABlog" }, { text: "But our love is not the expression of an impersonal life-force.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }, { text: "The movie clich\u00e9 of two people looking into each others\u2019 eyes and realizing simultaneously that they are in love is a model of this experience, which never really happens but is the presupposition of all that does.", slug: "the-terror-of-the-given", title: "The Terror of the Given", source: "GABlog" }], sources: [{ slug: "clr-121", title: "The End of Seinfeld", source: "Chronicles" }, { slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }] },
  { term: "Markets", slug: "markets", concept: "market", gloss: "Generators of information.", posts: 75, passages: [{ text: "Markets represent forms of delegation by the central authority\u2014markets are areas of social life that are not under direct sovereign supervision.", slug: "anthropomorphics-the-generativity-of-the-center", title: "The Generativity of the Center", source: "Book" }, { text: "Markets are created by states so as to provision their militaries when abroad, and money is supplied so as to enable soldiers to participate in those markets.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "Markets are real insofar as they are what people without direct authority for maintaining the social center do with knowledge, information and skills when they are being protected and bounded but not directly supervised by such authorities.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }, { slug: "what-are-we-talking-about-when-we-talk-about-the-market-gablog", title: "What are We Talking About When We Talk About the Market?", source: "GABlog" }] },
  { term: "Meaning", slug: "meaning", gloss: "Some interpretation and way of understanding a signifier, which is intended.", posts: 307, passages: [{ text: "Meaning is ultimately grounded in ostensivity\u2014to put it crudely, any utterance points at something, tells you what to notice.", slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { text: "Meaning is established rather differently in a scientific discipline organized around experimental protocols.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }, { text: "Of divine origin, but ultimately its meaning is rational and cognitive.", slug: "girard-on-the-passion", title: "Girard on the Passion", source: "GABlog" }], sources: [{ slug: "clr-661", title: "Communities of Meaning", source: "Chronicles" }] },
  { term: "Media", slug: "media", concept: "media", gloss: "Whatever enables the constitution of a scene.", posts: 279, passages: [{ text: "The media is already preparing the narrative of Obama the rescuer, \u201clike\u201d Lincoln and FDR.", slug: "barack-obama-the-greatest-president-ever", title: "Barack Obama, the Greatest President Ever!", source: "GABlog" }, { text: "The media are propaganda agencies of some power center or another\u2014the blogger Sundance at the Conservative Treehouse asserts that the CIA leaks to the Washington Post and the FBI to the New York Times .", slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }, { text: "The media is speech and writing publicized, transmitted, broadcast and preserved through technological and pedagogical\u2014scenic\u2014infrastructures.", slug: "media-as-infrastructural-translation", title: "Media as Infrastructural Translation", source: "Substack" }], sources: [{ slug: "media-as-scene-gablog", title: "Media as Scene", source: "GABlog" }] },
  { term: "Metalanguage", slug: "metalanguage", gloss: "Beginning with literacy and declarative speech, it\u2019s language that is autoreferential in that it can take the system of signification it itself exists in, and hold it before description and analysis: Metalanguage rather.", posts: 72, passages: [{ text: "The metalanguage is the anomaly, and therefore the crisis, not its distortions.", slug: "morality-and-reference", title: "Morality and Reference", source: "GABlog" }, { text: "Metalanguage is a way of solving this problem, and it\u2019s not surprising that the masters of writing would have found this solution to be an appropriate one to the problem of potentially infinite dissemination.", slug: "anthropomorphics-declarative-order-and-the-center", title: "Declarative Order and the Center", source: "Book" }, { text: "The most meaningful metalanguage is one that keeps attending to the distinction between language and metalanguage.", slug: "on-the-culling-of-cant", title: "On the Culling of Cant", source: "GABlog" }], sources: [{ slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }] },
  { term: "Metaphysics", slug: "metaphysics", gloss: "The working model for figuring and grounding meaning, particular to Western philosophy, originating in Plato as an instinct for deferring higher culture by grounding meaning in timeless declarative propositions rather than in the scene itself.", posts: 82, passages: [{ text: "Metaphysics is the attempt to rectify language when such events force language into self-reflexive states so that we can continue to look through language; originary grammar tries to articulate looking at language and with language with looking through language.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }, { text: "One way of breaking with Western metaphysics is by acknowledging the traditional character of all thought.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }, { text: "The best-known exponent of this version of metaphysics is the German social democratic philosopher Jurgen Habermas.", slug: "sovereign-commands-anarchistic-demands-gablog", title: "Sovereign Commands, Anarchistic Demands", source: "GABlog" }], sources: [{ slug: "clr-660", title: "From Kant to GA: Four Reflections", source: "Chronicles" }] },
  { term: "Mimesis", slug: "mimesis", concept: "mimesis", gloss: "Being able to see another social actor and mimic/learn from them: When you possess at least 2nd order Attentionality, and thus able to perceive other social actors, you\u2019re able to watch them and learn from them through mimesis.", posts: 65, passages: [{ text: "Mimesis is an excellent foundation for talking about the human because it provides a minimal version of human sameness that immediately opens onto a vista of human difference.", slug: "ancestries-and-meta-sovereignty", title: "Ancestries and Meta-Sovereignty", source: "GABlog" }, { text: "Mimesis is an adaptive learning behavior and as such can be considered a form of intelligence.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }, { text: "Mimesis is first of all positive and generative\u2014you learn from watching another if you can translate what he does into your own movements.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }], sources: [{ slug: "exhaustive-imitation", title: "Exhaustive Imitation", source: "Substack" }], },
  { term: "Mimetic Crisis", slug: "mimetic-crisis", concept: "mimesis", gloss: "All the memebers of the group participating in a pecking order fight.", posts: 60, passages: [{ text: "Gans assumes that the mimetic crisis is organized around some object of appetitive attention\u2014most likely some food source, perhaps a recent kill.", slug: "anthropomorphics-origin-and-hypothesis", title: "Origin and Hypothesis", source: "Book" }, { text: "Deferring some mimetic crisis is always the obverse of any observable act which suggests that the measure of any action is the relative imminence of that crisis and the delayed and distributed effects relative to that more or less likely crisis of the action taken.", slug: "originary-calculus", title: "Originary Calculus", source: "Substack" }, { text: "The victim does need to be consumed, and the emergent community does need to put its new sign to work to ensure this can be done in a communal and non-violent (or, sufficiently non- violent so that the mimetic crisis is not re-activated) manner.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [] },
  { term: "Mimetic Desire", slug: "mimetic-desire", concept: "mimesis", gloss: "Desiring something because someone else/others desire it: Mimetic Desire is the phenomenon where other people desiring something will increase your desire for it as well due to mimesis.", posts: 34, passages: [{ text: "We can certainly attribute to mimetic desire the \u201ccause\u201d for a particular act, but mimetic desire is always mediated through language.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "For Girard, this mimetic desire is a source of conflict and tension within societies, and it is mitigated through the act of focusing the cumulative mimetic desires of a society on a single individual who becomes a scapegoat.", slug: "nemesis-jouvenelian-liberal-model", title: "Book Review: Nemesis \u2014 The Jouvenelian vs. the Liberal Model of Human Orders (Ad", source: "Essay" }, { text: "Mimetic desire leads to the crisis; resentment comes in its wake, as the center now forbids us from satisfying our desire for the object located there.", slug: "sovereign-resentments", title: "Sovereign Resentments", source: "GABlog" }], sources: [] },
  { term: "Money", slug: "money", concept: "money", gloss: "Represents power over a piece of the Center: Money is a medium through which a piece of the Center can be aqcuired in a desacralized way.", posts: 158, passages: [{ text: "Money is used first of all for internal bureaucratic accounting in the ancient empires.", slug: "absolutist-economies-gablog", title: "Absolutist Economies", source: "GABlog" }, { text: "Money is both continuous and discontinuous with this history of exchanges with the center that constitutes humanity.", slug: "urbanomics", title: "Urbanomics", source: "GABlog" }, { text: "Money is the means by which agents compete within the networks so as to prove their usefulness to the network and to the center.", slug: "constrained-economies", title: "Constrained Economies", source: "GABlog" }], sources: [{ slug: "money-and-capital-as-media-and-power", title: "Money and Capital as Media and Power", source: "GABlog" }, { slug: "market-capillarism-gablog", title: "Market Capillarism", source: "GABlog" }, { slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }] },
  { term: "Morality", slug: "morality", gloss: "That which helps direct attention to the social Center: Morality as a mode of sharing attention enforces symmetry between those present in a social scene.", posts: 118, passages: [{ text: "Teleology and morality are fully implicit in the originary structure.", slug: "the-ends-of-man", title: "The Ends of Man", source: "GABlog" }, { text: "What kind of morality is this, then\u2014what does it consider more important than maintaining a livable social order?", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "When we think in terms of the relation between morality and power, for example, we are conceding the differentiation of the disciplines: morality is defined in one arena (\u201cPhilosophy,\u201d \u201cEthics\u201d), and power in another (\u201cPolitical Science\u201d).", slug: "dedifferentiation", title: "Dedifferentiation", source: "GABlog" }], sources: [{ slug: "clr-551", title: "The Moral Model", source: "Chronicles" }, { slug: "mimeticism-and-morality", title: "Mimeticism and Morality", source: "GABlog" }] },
  { term: "Myth", slug: "myth", gloss: "The stories and explanations generated around rituals in a sacrificial order.", posts: 63, passages: [{ text: "This understanding of myth is not obviously related to the emergence of the Big Man, but the increasingly complexity of intentions attributed to figures on the ritual scene (which, of course, can include animals and the elements) lays the groundwork for making sense of the Big Man\u2019s \u201cusurpation\u201d of the center.", slug: "the-marginal-anthropomorph", title: "The Marginal Anthropomorph", source: "GABlog" }, { text: "One (more) thing the Oedipus myth is about is human survival through love, minimally defined as the deferral of violence.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }, { text: "Under a ritual order, when the interlocking imperative exchanges don\u2019t work, myth is generated; with the evacuation of the ritual order, imperative failure leads to hypotheses (hypotheses are really articulations of particular ostensive-imperative-interrogative-declarative sequences).", slug: "data-mining-the-sentence", title: "Data Mining the Sentence", source: "Substack" }], sources: [] },
  { term: "Naming", slug: "naming", gloss: "Designating within a social order.", posts: 81, passages: [{ text: "Naming is performative, like christening a ship or marrying a couple, activities that manifest the most basic social traditions.", slug: "debts-and-deferences-gablog", title: "Debts and Deferences", source: "GABlog" }, { text: "Naming is the way the sovereign and his delegates (those who have been named by him) incorporate and authenticate institutions, authorities and practices.", slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { text: "Naming is also the most basic pedagogical act: nothing better marks the minimal hierarchy self-evident and modeled in any pedagogical act than saying \u201cwe\u2019ll call this ______\u201d Naming is the result of pedagogical practices of solicitation of the center.", slug: "anthropomorphics-the-end-of-secular-thinking", title: "The End of Secular Thinking", source: "Book" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Narrative", slug: "narrative", concept: "narrative", gloss: "A spoken or written account of some event.", posts: 138, passages: [{ text: "Narrative is always sacrificial, regardless of the best efforts of its most sophisticated practitioners.", slug: "hypothesis-practice-vs-narrative-the-iterative-center-gablog", title: "Hypothesis/Practice Vs. Narrative: The Iterative Center", source: "GABlog" }, { text: "Narrative is originary (at least implicitly), but literature, it seems to me, is not, since it evolved later.", slug: "what-is-originary", title: "What is originary?", source: "GABlog" }, { text: "We all have a sense of how, for example, a narrative is structured\u2014there is a hero, a goal, there are obstacles to achieving the goal, the hero overcomes them, and so on.", slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }], sources: [{ slug: "ap0302-narrative", title: "Originary Narrative", source: "AP Journal" }, { slug: "clr-346", title: "New Thoughts on Originary Narrative", source: "Chronicles" }] },
  { term: "Nihilism", slug: "nihilism", gloss: "Contradicting Imperatives: When faced with multiple Imperatives that contradict one another it gives rise to the feeling of meaninglessness and nihilism.", posts: 13, passages: [{ text: "The nihilism of much modern art and modern thought is best understood as a protest bemoaning the absence of such a world.", slug: "virality-and-sovereignty", title: "Virality and Sovereignty", source: "GABlog" }, { text: "Nihilism sets in once public battles seem to be about nothing\u2014a combat with no real victor, because victories that are muddied, or dissipate, or are endlessly re-litigated , can no longer be appreciated as a contest.", slug: "exodus-from-the-dead-end-of-history-2", title: "Exodus from the Dead End of History, 2", source: "GABlog" }, { text: "Cynicism and nihilism can only be a local phenomenon indulged in by the privileged.", slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }], sources: [] },
  { term: "Nominalization", slug: "nominalization", gloss: "Making a noun (name) out of a non-noun.", posts: 13, passages: [{ text: "A nominalization is \u201credeemed\u201d in the same way, through the organization of \u201ccongregants\u201d who can generate ostensives singularizing the nominalization.", slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }, { text: "We could construct paths to nominalization producing these concepts, which are metaphors drawn from machinery and statistics.", slug: "the-disciplines-the-imperative-of-the-center-the-generative-thought-experiment", title: "The Disciplines, the Imperative of the Center, the Generative Thought Experiment", source: "GABlog" }, { text: "Even \u201cthought\u201d is such a nominalization of the verb \u201cthink\u201d\u2014we can have \u201cthoughts,\u201d but there is also a whole world of \u201cthought,\u201d with its own history.", slug: "accessing-the-ostensive-within-the-declarative", title: "Accessing the Ostensive within the Declarative", source: "GABlog" }], sources: [{ slug: "ap2402-2402katz", title: "Generative Anthropology as the One Big Discipline", source: "AP Journal" }, { slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }] },
  { term: "Occupied Center", slug: "occupied-center", concept: "the-center", gloss: "The Center that orders (other Centers).", posts: 26, passages: [{ text: "The occupied center is still taken as a kind of accident, acceptable only insofar as we can reduce the occupant to the implementation of one of these concepts.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "One\u2019s place in relation to the signifying center is fundamentally questionable, even if one\u2019s relation to the occupied center is not\u2014hence the discrepancy.", slug: "anthropomorphics-talk-of-the-center", title: "Talk of the Center", source: "Book" }, { text: "The discrepancy between signifying and occupied center will generate struggles over the occupancy of the center, which struggles then inform and divide the disciplines.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }], sources: [{ slug: "way-way-after-sacral-kingship-gablog", title: "Way, Way, After Sacral Kingship", source: "GABlog" }, { slug: "form-and-paradox", title: "Form and Paradox", source: "GABlog" }, { slug: "sacral-kingship-and-after-preliminary-reflections", title: "Sacral Kingship and After: Preliminary Reflections", source: "GABlog" }] },
  { term: "Originary Event", slug: "originary-event", concept: "originary-scene", gloss: "The event where language and the human emerged: The specific event where the aborted gesture of appropriation finally succeeded, which inaugurated language and the human.", posts: 77, passages: [{ text: "The originary event is a sample of humanity because all members of the group became sampling samples there.", slug: "the-sign-substack", title: "The Sign", source: "Substack" }, { text: "The originary event is an instance of successfully seeing what happens when we do this to that\u2014meaning is achieved.", slug: "disciplinarity-and-the-center", title: "Disciplinarity and the Center", source: "Substack" }, { text: "The originary event is also the origin of resentment: the same sacred Being that preserves the community restrains desire while endowing the object with a sacrality that enhances its desirability.", slug: "the-anthropoetics-of-power", title: "The Anthropoetics of Power", source: "Essay" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Originary Grammar", slug: "originary-grammar", concept: "originary-grammar", gloss: "The reading of signs and semiotic practices as to functionally preserve linguistic presence, involving inquiry into the most easily iterated modes in which to share attention: Constituted by the Ostensive, Imperative, In.", posts: 58, passages: [{ text: "Anyone interested in what my originary grammar is doing at the moment, here is my latest post on JCRT Live http://jcrt.typepad.com/jcrt_live/2009/03/originary-grammar-part-2.html", slug: "originary-grammar", title: "originary grammar", source: "GABlog" }, { text: "Processing the primes through originary grammar is the path toward making language programming and making it currency, against, I would guess, the discoverers of both these linguistic hypotheses (but, maybe, we can redeem Wierzbicka\u2019s and Gans\u2019s intentions by prolonging them through the stacks).", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }, { text: "The metalanguage of literacy produces a fabricated present contrived out of various match-ups between categories deposited in the mind and categories deposited in reality\u2014the purpose of originary grammar is to deconstruct such a present into the stacked scenes presented with the problem of succession.", slug: "techno-grammar", title: "Techno-Grammar", source: "Substack" }], sources: [{ slug: "originary-grammar-and-post-sacrificial-semiotic-agency", title: "Originary Grammar and Post-Sacrificial Semiotic Agency", source: "GABlog" }, { slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }], },
  { term: "Originary Hypothesis", slug: "originary-hypothesis", concept: "originary-scene", gloss: "A hypothesis on how human language emerged: The Originary Hypothesis is an empirically unverifiable hypothesis about how human language emerged in an event, making it categorically different than animal\u2019s indexical signalling.", posts: 160, passages: [{ text: "The originary hypothesis is easily summed up in a couple of paragraphs, at most, and all it really assumes is that human beings are mimetic creatures.", slug: "the-originary-hypothesis-in-itself", title: "The Originary Hypothesis in Itself", source: "Substack" }, { text: "Here, the obstacle in the way of perceiving the originary hypothesis is a refusal of paradoxical thinking.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Does that mean that one doesn\u2019t claim that the originary hypothesis is true, or gets us closer to the truth of human being than other ways of thinking?", slug: "mimetic-culture-liminal-culture", title: "Mimetic Culture, Liminal Culture", source: "GABlog" }], sources: [] },
  { term: "Originary Memory", slug: "originary-memory", gloss: "The first human memory which we all share with one another as beings capable of using the uniquely human sign: It is the unconsciously held memory of the configuration of the scene, the minimal memory of mimetic interactivity.", posts: 8, passages: [{ text: "Cognition as Originary Memory The shift in focus, in cognitive theory, from the relation between mind and objects in the world to the relation between minds mediated by inter-subjectivity, brings it into dialogue with originary thinking.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "Inasmuch as originary memory reproduces a memory of the whole scene and the whole event, all forces tend toward the community\u2019s peaceful acceptance of the new object: the usurper wishes to minimize the risk of violence to himself, and the community wishes to minimize the risk to itself.", slug: "anthropomorphics-the-center-and-the-declarative", title: "The Center and the Declarative", source: "Book" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }, { slug: "originary-memory", title: "Originary Memory", source: "GABlog" }] },
  { term: "Originary Satire", slug: "originary-satire", gloss: "The representation of the temptation of transgression within the impossibilization of victimization.", posts: 24, passages: [{ text: "Originary satire is clearly lashon hara, which means I have a differend to work with here.", slug: "idiom-and-the-differend", title: "Idiom and the differend", source: "Substack" }, { text: "A kind of originary satire is required here, in which one invents the gestures that display the terminal points of actions taken within the oscillation of debt issuance on the one hand, and debt enforcement on the other (roughly, the central banks and the national security/intelligence agencies).", slug: "exhaustive-imitation", title: "Exhaustive Imitation", source: "Substack" }, { text: "The originary satire which is simultaneously absolute idiomatic infiltration of central intelligence is the only sustainable mode of inscription now.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }], sources: [{ slug: "language-policy", title: "Language Policy", source: "GABlog" }, { slug: "logocentrism-media-and-originary-satire", title: "Logocentrism, Media, and Originary Satire", source: "GABlog" }, { slug: "the-paradoxical-telos-of-the-aesthetic-gablog", title: "The Paradoxical Telos of the Aesthetic", source: "GABlog" }] },
  { term: "Originary Scene", slug: "originary-scene", concept: "originary-scene", gloss: "The series of moments whereby the originary event was instantiated, which is coeval with all significance.", posts: 281, passages: [{ text: "The originary scene is commemorated in ritual, and the specific movements, arrangements and props that organize the scene through the accretion of the memories of the group in its ongoing dialogue with the center is the origin of technology.", slug: "mimesis-center-auto-immunology", title: "Mimesis, the Center and Auto-Immunology: A Review of Psychopolitical Anaphylaxis", source: "Essay" }, { text: "Following the sparagmos on the originary scene is the iteration of the scene in the ritual.", slug: "quantity", title: "Quantity", source: "GABlog" }, { text: "The paradoxes of deferral we see on the originary scene are enduring features of the human.", slug: "anthropomorphics-origin-and-hypothesis", title: "Origin and Hypothesis", source: "Book" }], sources: [], },
  { term: "Originary Sign", slug: "originary-sign", concept: "the-sign", gloss: "The central object becomes the first Sign: During the Originary Event, the central object becomes the first Sign, repelling the participants attempt at appropriating it, avoiding a mimetic conflict.", posts: 38, passages: [{ text: "The originary sign is iconic and ostensive, because it is constitutive\u2014that is, it establishes the very conditions under which iconic and ostensive signs are possible; but it does so ostensively and iconically.", slug: "a-brief-note-on-terminology", title: "A brief note on terminology", source: "GABlog" }, { text: "The originary sign had to be gesture\u2014it couldn\u2019t be imagined as a sound, or a line drawn on the ground.", slug: "self-evidency", title: "Self-Evidency", source: "GABlog" }, { text: "The originary sign creates a radical difference between the meaningful central object, on the one hand, and everything else, on the other.", slug: "anthropomorphics-a-grammar-of-the-social", title: "A Grammar of the Social", source: "Book" }], sources: [] },
  { term: "Originary Thinking", slug: "originary-thinking", gloss: "Means that language has always been about deferral.", posts: 84, passages: [{ text: "I don\u2019t deny that originary thinking is also compatible with liberalism, just that it only and intrinsically is so.", slug: "the-originary-hypothesis-and-reactionary-thinking", title: "The Originary Hypothesis and Reactionary Thinking", source: "GABlog" }, { text: "Ultimately, originary thinking is a way of tracing all the frames it comes across back to their origins, and through those origins, the origin of language and humanity.", slug: "within-language", title: "Within Language", source: "GABlog" }, { text: "The task for originary thinking is explore the overlapping terrains covered by this sprawling vocabulary, and make sense of them as so many ways of being signifying beings.", slug: "selfy", title: "Selfy", source: "GABlog" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Ostensive", slug: "ostensive", concept: "ostensive-imperative-declarative", gloss: "A gesture or utterance issued where its signified is present.", posts: 218, passages: [{ text: "The ostensive is meaningless in the absence of its referent; the declarative can do without a real-world referent.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The ostensive is the \u201ceating\u201d in which we find the \u201cproof of the pudding.\u201d This is the kind of thing a disciplinary space is interested in\u2014what counts as a sign that an imperative has been completed?", slug: "more-on-the-proper-use-of-declarative-sentences", title: "More on the Proper Use of Declarative Sentences", source: "GABlog" }, { text: "The syntactic form that corresponds to the ostensive is, I would say, the exclamation : \u201cwhat a lovely day!\u201d expresses that originary sense of gratitude as does \u201chow awful!\u201d because the latter expression equally presupposes some non-awful condition that allows us all to immediately recognize how awful the one indicated is.", slug: "common-sense", title: "Common Sense", source: "GABlog" }], sources: [{ slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }, { slug: "clr-539", title: "The New Origin of Language Part 4: Linguistics of the Ostensive", source: "Chronicles" }] },
  { term: "Paradox", slug: "paradox", gloss: "A property only present in, though makes possible, systems of representation.", posts: 110, passages: [{ text: "Paradox is constitutive of power and sovereignty as well, a point of supreme importance for absolutism.", slug: "power-and-paradox-gablog", title: "Power and Paradox", source: "GABlog" }, { text: "The paradox is contained within the ethical dimension as well: the deferred object becomes all the more desirable the more barred from appropriation it is.", slug: "the-sovereign-remembering-of-names", title: "The Sovereign Remembering of Names", source: "GABlog" }, { text: "Of course, this paradox is meant to examine our assumptions regarding \u201cidentity.\u201d So, it\u2019s still the same ship insofar as it\u2019s still called the S.S.", slug: "crowding-out-the-political-gablog", title: "Crowding Out the Political", source: "GABlog" }], sources: [{ slug: "clr-580", title: "Paradox", source: "Chronicles" }, { slug: "clr-390", title: "The Fundamental Paradox of Signification", source: "Chronicles" }] },
  { term: "Performativity", slug: "performativity", gloss: "The power of language to effect change in the world.", posts: 17, passages: [{ text: "The seemingly radical implication of performativity is that social roles rely upon ongoing participation and therefore revision and adaptation and can therefore always be taken up differently.", slug: "centrifugal-signifying", title: "Centrifugal Signifying", source: "Substack" }, { text: "This doesn\u2019t mean rule by \u201cnerds,\u201d because linguistic performativity means leading men, and men dedicated to the most rigorous testing of the more daring hypotheses.", slug: "demand-and-the-grammar-of-desire", title: "Demand and the Grammar of Desire", source: "Substack" }, { text: "It\u2019s easy to overlook these modes of performativity, or to examine them only in some kind of protest mode which pretends to imagine a return to an earlier form of liberty, and thereby remain focused on the predations of social media.", slug: "the-sentence-as-metric", title: "The Sentence as Metric", source: "Substack" }], sources: [{ slug: "clr-570", title: "The Originary Performative", source: "Chronicles" }] },
  { term: "Politics", slug: "politics", gloss: "Struggle over language.", posts: 287, passages: [{ text: "Politics is sure to channel such resentments, compromising the independence of independent arbiters of insurance contracts.", slug: "health-care", title: "Health Care", source: "GABlog" }, { text: "Politics is most effective when the actors represent cleavages within the audience and reflect upon the meta- or constitutive rules governing the political space itself.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }, { text: "Politics is for protecting the dominion of habit and helping it become self-reflexive and open to novel compositions.", slug: "habit-and-errors-and-composition", title: "Habit and Errors and Composition (Adam Katz)", source: "Essay" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }] },
  { term: "Post-Sacrificial", slug: "post-sacrificial", gloss: "The culture following the breakdown of sacrificial culture, or imperative exchange.", posts: 36, passages: [{ text: "The post-sacrificial epoch would better (and more positively) be called the epoch of the absolute imperative, a concept I take from Philip Rieff.", slug: "can-networks-crowd-out-markets-gablog", title: "Can Networks Crowd Out Markets?", source: "GABlog" }, { text: "Post-sacrificial civilization (accomplished via the Judaic, Biblical, and Christian revelations in the West and otherwise\u2014via Buddhism, Taoism, Confucianism, etc., elsewhere) is the ongoing effort to bring that category into focus.", slug: "fraud-and-force", title: "Fraud and Force", source: "GABlog" }, { text: "Post-sacrificial modes of being involve giving over our desires and resentments to the center in the knowledge we will have to sustain our attention towards the center so as to be worthy of when those desires and resentments come back transformed into imperatives from the center.", slug: "total-semiotics-or-exteriorizing-the-interiors", title: "Total Semiotics, or Exteriorizing the Interiors", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }] },
  { term: "Power", slug: "power", concept: "power", gloss: "[The moving of frames in order to produce greater shared attention].", posts: 550, passages: [{ text: "Power is both a priori and provisional, a location and its occupant.", slug: "power-and-paradox-gablog", title: "Power and Paradox", source: "GABlog" }, { text: "Power is ontologically prior to and causative of, markets and all the rest.", slug: "anthropomorphics-center-and-distribution", title: "Center and Distribution", source: "Book" }, { text: "Power means thwarting the ambitions of whoever would break ranks and rush to center.", slug: "the-two-charismas", title: "The Two Charismas", source: "GABlog" }], sources: [{ slug: "power", title: "Power", source: "GABlog" }, { slug: "centering", title: "Centering", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Practice", slug: "practice", gloss: "Doing something so that something happens as a result of what you have done: A Practice is intentionally engaging in specific actions to obtain specific outcomes.", posts: 287, passages: [{ text: "The practice is the transposition of a sample from one field to another, in such a way that the fields are converted into elements appropriable by the practice.", slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }, { text: "The practice is to operationalize the meanings you encounter (as, e.g., in calling something \u201chard\u201d means a certain kind and degree of force would be needed to alter its surface) and elicit the stack of scenes and grammatical stack that would make the sample meaningful, or more meaningful, or put on the path toward meaning.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }, { text: "A practice is a doing in the middle of things that are happening.", slug: "design-imitation-and-the-transfer-translation", title: "Design, Imitation, and the Transfer Translation", source: "GABlog" }], sources: [{ slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }, { slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }] },
  { term: "Presencing", slug: "presencing", gloss: "The exchange of signs between participants upon a Scene.", posts: 14, passages: [{ text: "The model for this kind of semiotic presencing is sovereignty: you acknowledge that my utterance has brought into being a world you must find your way in and sustain.", slug: "absolutist-epistemology", title: "Absolutist Epistemology", source: "GABlog" }, { text: "Transcendence has us protect the separateness of the object; presencing is interested in the continuity of the scene\u2014the object, then, would tend to devolve into a series of more or less premeditated pretexts for doing so.", slug: "beginnings-in-the-middle-presence-and-the-infinitesimal", title: "Beginnings in the Middle: Presence and the Infinitesimal", source: "GABlog" }, { text: "That\u2019s the work of stacked presencing\u2014to perform the stack of scenes as an ever problematic, never guaranteed prolongation of the originary scene.", slug: "stacked-presencing", title: "Stacked Presencing", source: "Substack" }], sources: [{ slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }] },
  { term: "Rationality", slug: "rationality", gloss: "The process of working abstract formal objects into opposing binaries, and evaluating their ordering according to truth-value and logical consistency.", posts: 22, passages: [{ text: "The Axial Age can be defined as a new mode of rationality transcending ritual or a kind of secularization in which new modes of universal understanding transcend narrow or \u201ccompact\u201d social groupings, drawing upon the simultaneous emergence of Greek Philosophy, the Hebrew prophets and Asian phenomena like Buddhism and Confucianism.", slug: "the-pointman", title: "The Pointman", source: "Substack" }], sources: [{ slug: "ap1202-frank1", title: "Originary Science, Originary Memory Frankenstein and the Problem of Modern Scien", source: "AP Journal" }] },
  { term: "Reactionary", slug: "reactionary", gloss: "Recuperating the Center.", posts: 62, passages: [{ text: "Reactionary politics wants the levels of adjudication all named up.", slug: "the-ministry-of-true-naming", title: "The Ministry of True Naming", source: "GABlog" }, { text: "Reactionary Future \u2019s explanation for the Black Lives Matter riots brings out the strengths and distinction of absolutism as a theory of social order.", slug: "the-three-resentments", title: "The Three Resentments", source: "GABlog" }, { text: "Reactionary politics derives from this approach ever more detailed maps of the power sprawl that constitutes contemporary disorder and a model of disciplined attempts at securing power.", slug: "reaction-as-political-praxis", title: "Reaction as Political Praxis", source: "GABlog" }], sources: [] },
  { term: "Reification", slug: "reification", gloss: "A static metaphysic.", posts: 13, passages: [{ text: "To name is both to reify, to create a role independent of whoever fills it, and to singularize, insofar as we can always distinguish between those who more or less adequately or authoritatively \u201cinhabit\u201d that name. the reification is then less an alienation or objectification than the creation of a new set of capacities.", slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }], sources: [] },
  { term: "Reliability", slug: "reliability", gloss: "Social-moral coherence: In governance, [Reliability is about creating social-moral coherence. This stands opposite to \u2018predictability\u2019.].", posts: 24, passages: [{ text: "We could hypothesize that in the gift economy and the honor/shame moral economy that goes along with it, it is competition among the performers, whose reliability is at stake at every instant, that is the issue; in a fully fledged market economy, it is competition among objects, and we don\u2019t even have to see the performers.", slug: "a-little-social-theory", title: "A Little Social Theory", source: "GABlog" }, { text: "Here is where a real marker of political reliability will be one\u2019s ability to resist the temptation to turn these accusations back on one\u2019s accusers, which continues the transformation of politics into attempts to be licensed as an arbiter of unacceptable speech.", slug: "anthropomorphics-maintaining-the-present-of-the-center", title: "Maintaining the Present of the Center", source: "Book" }, { text: "All this would depend, of course, upon the reliability of the firm\u2019s judgments\u2014only insofar as those judgments and the reasoning offered for them were seen to be impartial could its success as a company and metric of civilizational layering be assured.", slug: "thirdness", title: "Thirdness", source: "Substack" }], sources: [] },
  { term: "Representation", slug: "representation", gloss: "The Deferral of Desire: [Representation is the externalization of an injunction against our Desire from our Desires themselves.] You are both the one Desiring and the one Desiring to defer your Desire.", posts: 184, passages: [{ text: "The deferral of violence through representation is what we are \u201cmeant\u201d to do.", slug: "the-ends-of-man", title: "The Ends of Man", source: "GABlog" }, { text: "But more importantly, no symbolic representation is involved with the alpha male\u2019s position in the group.", slug: "a-unified-field-theory-of-victimocracy", title: "A Unified Field Theory of Victimocracy", source: "GABlog" }, { text: "Every representation does need to posit some scene upon which all \u201creceiving\u201d the representation are virtually present.", slug: "the-declarative-order-and-inquiry", title: "The Declarative Order and Inquiry", source: "GABlog" }], sources: [] },
  { term: "Resentment", slug: "resentment", concept: "resentment-victimary", gloss: "A refusal to release an other from Imperative you consider them bound by: Resentment is your fulfilling of an Imperative, having the reciprocal Imperative you issue go unfulfilled, while not letting that reciprocal Imperative lapse.", posts: 307, passages: [{ text: "Resentment is the emotion (?) or attitude (?) one has towards whomever denies you your desire.", slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }, { text: "Resentment is directed toward this second function of the object (or, to be a bit Lacanian, Object)\u2014it bars the realization of desire.", slug: "the-three-resentments", title: "The Three Resentments", source: "GABlog" }, { text: "Resentment is the imitation of the central presence, the enactment of the rule that is derived from the object in the midst of the failure to clear the field for desire.", slug: "more-problems-in-the-concept-of-imitation", title: "More problems in the concept of imitation", source: "GABlog" }], sources: [{ slug: "resentment", title: "Resentment", source: "Substack" }, { slug: "praxis", title: "Praxis", source: "GABlog" }, { slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }] },
  { term: "Rights", slug: "rights", gloss: "Privilege and delegated autonomy that is declared prior to the necessary coordination (attention and naming) and mechanisms (material enforcement by real sovereigns) required to have delegated them in the first place: Ri.", posts: 259, passages: [{ text: "We could say, instead, that rights are rooted in one\u2019s participation in a gift economy.", slug: "the-right-of-the-idiom-continued", title: "The Right of the Idiom, continued", source: "GABlog" }, { text: "Demands for rights are deliberately destructive of meaning, because the world of meanings is what prevented attention from being lavished on the plaintiff.", slug: "the-meaning-of-meaning-and-metalanguage", title: "The Meaning of Meaning, and Metalanguage", source: "GABlog" }, { text: "In such societies, persons, property, and rights are defended by recourse to third parties, usually courts, police, and so forth, that, if necessary, wield violence on their behalf.", slug: "up-from-victimhood", title: "Up from Victimhood", source: "GABlog" }], sources: [{ slug: "ap2302-2302katz", title: "Power and Paradox", source: "AP Journal" }, { slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }] },
  { term: "Ritual", slug: "ritual", concept: "ritual", gloss: "Commemoration and scene-setting: Rituals commemorate earlier events and configures the Scene in a specific way in accordance with the commemorated Scene being brought into presence in the present.", posts: 280, passages: [{ text: "Ritual is modified with the emergence of the imperative out of the ostensive.", slug: "coming-to-a-head", title: "Coming to a Head", source: "GABlog" }, { text: "Ritual is an exchange with the center: the participant fulfills some command of the center while making a request of the center.", slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }, { text: "Ritual is most fundamentally commemoration and scene-setting.", slug: "media-as-ritual", title: "Media as Ritual", source: "Substack" }], sources: [{ slug: "media-as-ritual", title: "Media as Ritual", source: "Substack" }, { slug: "languaging-practices", title: "Languaging Practices", source: "GABlog" }, { slug: "the-imperative-constant", title: "The Imperative Constant", source: "GABlog" }], },
  { term: "Sacrality", slug: "sacrality", concept: "the-sacred", gloss: "The Thematization of the human Paradox.", posts: 73, passages: [{ text: "The underlying identity of significance and sacrality is not a mere metaphor.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "His sacrality is more abstract, and less bound up with the ebb and flow of everyday life.", slug: "power-and-paradox-pdf", title: "Power and Paradox (Adam Katz)", source: "Essay" }, { text: "In that case, the question of sacrality is suspended, because determining something to be sacred and hence the source of the good, the true, etc., would then invalidate the conversation.", slug: "secular-thinking", title: "Secular Thinking", source: "Substack" }], sources: [{ slug: "clr-531", title: "Paradox and the Sacred", source: "Chronicles" }] },
  { term: "Satire", slug: "satire", gloss: "Bringing attention to reified bureaucracies: Satire is when you try to apply a reified bureaucracy in a different context/situation than it\u2019d normally be applied.", posts: 51, passages: [{ text: "Satire is the medium in which such a winnowing out would be enacted, and for the satire to be trustworthy the ruler would have to be on the stage as well.", slug: "paradoxicality", title: "Paradoxicality", source: "GABlog" }, { text: "Satire is an attempt to further refine names until they position someone or something or some event on the originary scene, retrieved prior to the second revelation.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "Satire is not really interested in being realistic, or in improvement\u2014it just wants to show us what inevitably gets forgotten in more acceptable forms of representation.", slug: "esthetic-oscillations", title: "Esthetic Oscillations", source: "GABlog" }], sources: [] },
  { term: "Scapegoating", slug: "scapegoating", concept: "scapegoating", gloss: "Deferring authority to something outside yourself.", posts: 106, passages: [{ text: "Scapegoating is particularly alarming today, with the weapons of mass destruction at our disposal and the ways instantaneous media facilitate mob-like reactions to events.", slug: "speaking-your-mind-minding-your-speech", title: "Speaking Your Mind, Minding Your Speech", source: "GABlog" }, { text: "Scapegoating is a practice of subtracting likeness from the othered, making likeness among those who do the othering less threatening; to acknowledge various ways of identifying the same amongst the like is to make it possible to lower and raise the threshold of differentiation as needed.", slug: "selving", title: "Selving", source: "Substack" }, { text: "But there is some question as to whether such resistance to scapegoating is more than just \u201cpragmatic,\u201d with the resentment being enacted in some ritual or aesthetic manner.", slug: "fraud-and-force", title: "Fraud and Force", source: "GABlog" }], sources: [{ slug: "beyond-post-sacrificial", title: "Beyond \u201cPost-Sacrificial\u201d", source: "GABlog" }] },
  { term: "Scene", slug: "scene", gloss: "A scene is either an implicit or explicit context mutually defined and understood by a multiplicity of language users.", posts: 446, passages: [{ text: "The scene is completed simply by having a \u201ccritical mass\u201d of participants see each other this way, because enough people seeing each other this way and showing that they see each other this way is the sign.", slug: "center-and-origin-the-name-of-the-center-and-centered-names", title: "Center and Origin: The Name-of-the-Center and Centered Names", source: "GABlog" }, { text: "The scene is fundamentally contingent for him, and the various errors in emission upon the scene are smoothed out or \u201cnormed\u201d; nor does he have any thought as to what will come after the scene\u2013he will participate in the sparagmos like everyone else, but he has been assimilated to the group, which can take care of itself, by that point.", slug: "habits-error-assignments", title: "Habits, Error, Assignments", source: "GABlog" }, { text: "The scene is designed so as to make that action the only conceivable one.", slug: "writing-as-technics", title: "Writing as Technics", source: "Substack" }], sources: [{ slug: "ap2202-2202matthews", title: "Anti-Hierarchical Culture in Media-Based Creative Collectives: Sketching Origina", source: "AP Journal" }, { slug: "ap2302-2302katz", title: "Power and Paradox", source: "AP Journal" }, { slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }] },
  { term: "Scene of Representation", slug: "scene-of-representation", gloss: "The exchange of signs between a participant upon one scene and another, a \u201cstranger\u201d to the scene to whom one presents the results of the scene: \u2018Summarizing\u2019 and presenting the results of an [established] Scene.", posts: 20, passages: [{ text: "The scene of representation is still primarily a place of deferral of conflict, not contemplation of a model of reality.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Anybody who uses language is a self endowed with free will; to use the sign on the scene of representation is to be a human self.", slug: "selfy", title: "Selfy", source: "GABlog" }, { text: "The scene of representation, however, is not just a rhetorical model of language as communication, but rather a model of transcendence or meaning.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }], sources: [{ slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }] },
  { term: "Scenic design", slug: "scenic-design", concept: "scenic-design", gloss: "Construction scenes such that whoever is placed at the center is connected with what is an increasingly exclusive and direct imperative relation with all on the periphery: Involving an unceasing flurry of supplementary i.", posts: 60, passages: [{ text: "So, the work of scenic design is the translation of events designed into narrative form into the terms of a possible practice.", slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }, { text: "The purpose of scenic design is revelation: scenes should be designed so as to maximize information coming from the center, which is to say anomalies generated by the selvings across those scenes.", slug: "literature-as-para-data-and-intelligence-exchange-with-the-center", title: "Literature as Para-Data and Intelligence Exchange with the Center", source: "Substack" }, { text: "Scenic design, extracting and deriving from the scene, is the event.", slug: "programming", title: "Programming", source: "Substack" }], sources: [{ slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }], },
  { term: "Scientism", slug: "scientism", gloss: "Secularization or the disconnection of a scientific Disciplinary Space, from its own moral history as an Institutional practice.", posts: 9, passages: [{ text: "What is ignored by this scientism is the anthropological origins of the juridical form, which lie in the suppression of the vendetta (which would mean that the discussion of appropriate punishment must always find reference to some lower threshold that might reignite the vendetta).", slug: "originary-calculus", title: "Originary Calculus", source: "Substack" }, { text: "Originary grammar should supersede scientism while preserving all the intellectual advances of science.", slug: "the-worlding-event", title: "The Worlding Event", source: "GABlog" }, { text: "\u201cscientism,\u201d a fellow participant in an online forum and (I think) the owner of an (eponymous) excellent twitter account, sees in the modern state a dialectic of centralization and fragmentation.", slug: "sovereignty-and-standardization", title: "Sovereignty and Standardization", source: "GABlog" }], sources: [] },
  { term: "Semantic Primes", slug: "semantic-primes", gloss: "A basic vocabulary shared by all languages in the world: Anna Wierzbicka studied all languages in the world and found that all languages share approximately 200 words that all have the same meaning in all languages.", posts: 34, passages: [{ text: "The \u201cspeech words\u201d among the semantic primes are \u201csay,\u201d \u201cwords,\u201d \u201ctrue\u201d (not even \u201cfalse\u201d).", slug: "moral-thresholds", title: "Moral Thresholds", source: "GABlog" }, { text: "The Natural Semantic Primes are on the one hand the simplest, most commonplace words and the most mysterious\u2014how is it, exactly, that we \u201cthink,\u201d \u201csay,\u201d \u201cknow,\u201d \u201cdo\u201d and so on?", slug: "tokenization", title: "Tokenization", source: "Substack" }, { text: "The idioms I\u2019ve been creating out of a reduction of scenic thinking to Anna Weirzbicka\u2019s Natural Semantic Primes is, then, intended to become the language of a team, or teams of teams, operating directly on the field of probability.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }], sources: [] },
  { term: "Shared Attention", slug: "shared-attention", gloss: "Pre-linguistic attention is typically referred to as shared attention, distinguished from linguistic, and meaningful joint-attention.", posts: 46, passages: [{ text: "Indeed, the center must be marked first of all, insofar as the participants in the event attend from the sign/gesture to the object; but the effect of this shared attention is to have everyone attend from the object as sacred to each and every one\u2019s profane desire for the object, culminating in the regulated sparagmos.", slug: "the-right-of-the-idiom-3", title: "The Right of the Idiom, 3", source: "GABlog" }, { text: "It is this first example of joint shared attention that is the beginning of human language.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "There are two ways shared attention can be interrupted: first, through some kind of distraction; second, through some kind of fixation.", slug: "flipping-the-conference", title: "Flipping the Conference", source: "GABlog" }], sources: [] },
  { term: "Sign", slug: "sign", concept: "the-sign", gloss: "A sound-image affixed or conferred meaning, in reference to an object which may have no correlation to the form of the sound-image, especially in declarative signing: à la Saussure, the sign is split into signifier and signified.", posts: 337, passages: [{ text: "The sign is both the invention and the memory of that insight, an insight which must have been available on the scene to someone positioned so as to witness a simultaneous escalation and de-escalation in different \u201csectors\u201d of the scene.", slug: "speaking-your-mind-minding-your-speech", title: "Speaking Your Mind, Minding Your Speech", source: "GABlog" }, { text: "The sign designates the central object as taboo or sacred: too desirable and dangerous to be appropriated.", slug: "why-generative-anthropology", title: "Why Generative Anthropology (Peter Goldman)", source: "Essay" }, { text: "By its nature, the sign is an individual act, even when performed with others.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }], sources: [{ slug: "clr-340", title: "Fr\u00e8re Jacques", source: "Chronicles" }] },
  { term: "Significance", slug: "significance", gloss: "The quality an object possesses in its meaningfulness or relevancy as Sacred or Desirable.", posts: 80, passages: [{ text: "The ostensive offers a \u201cprofane\u201d version of the scene, an intentional model of the universe limited to a single present reality, whose significance is presumed to require immediate attention.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "I think we could say that lowering the threshold of significance is the way we conserve linguistic presence: what threatens linguistic presence is the loss of a shared center that we could point to; by lowering the threshold of significance we place a newly identified object at that center.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "The man of resentment suffers from his finitude, not because he knows his life is finite, but because he feels his significance is finite.", slug: "on-love-resentment-and-the-early-chronicles", title: "On Love, Resentment and the Early Chronicles", source: "Substack" }], sources: [{ slug: "clr-536", title: "The New Origin of Language Part 2: Formal and Institutional Representation", source: "Chronicles" }] },
  { term: "Signification", slug: "signification", gloss: "To represent something using signs.", posts: 28, passages: [{ text: "In contrast, the signification-criterion is roughly speaking that of truth, al though only declarative sentences possess a genuine truth-value.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "Attending to the tacit knowing enabling any signification recuperates distractions by using them to break up the fixations that interfere with our attending to the overlapping margins of our idioms that make language learning possible.", slug: "flipping-the-conference", title: "Flipping the Conference", source: "GABlog" }, { text: "Any act of signification aims at changing the field of probabilities within which it is situated.", slug: "idioms-as-operationalized-samples", title: "Idioms as Operationalized Samples", source: "Substack" }], sources: [{ slug: "clr-536", title: "The New Origin of Language Part 2: Formal and Institutional Representation", source: "Chronicles" }, { slug: "clr-537", title: "The New Origin of Language Part 3: The Ostensive", source: "Chronicles" }] },
  { term: "Signifying Center", slug: "signifying-center", concept: "the-center", gloss: "Is the meaning with which we imbue the Occupied Center and all its branches: The Center is also the source of meaning, coherence, and consistency, which is what makes an order an order.", posts: 24, passages: [{ text: "One\u2019s place in relation to the signifying center is fundamentally questionable, even if one\u2019s relation to the occupied center is not\u2014hence the discrepancy.", slug: "anthropomorphics-talk-of-the-center", title: "Talk of the Center", source: "Book" }, { text: "Through these pedagogical and moral practices the signifying center is brought to bear on the occupied center, and imperative gap closed.", slug: "anthropomorphics-the-center-and-imperative-authority", title: "The Center and Imperative Authority", source: "Book" }, { text: "The signifying center, which under sacral conditions was supplemented by narrative and liturgical knowledge on the part of supplicants, is now constituted by attempts to apply remembered promises from the occupied center to the very scenic (technological) conditions constructing the memory.", slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }], sources: [{ slug: "from-metapolitics-to-politics", title: "From Metapolitics to Politics", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "Signing", slug: "signing", gloss: "The locus of agency.", posts: 10, passages: [{ text: "It\u2019s starting to look like fewer men are signing up\u2014how many would be enough to make a difference?", slug: "system-s-theory", title: "System\u2019s Theory", source: "GABlog" }, { text: "But now that GA has provided the birth of our signing ability with a plausible real-world foundation, the problems of both philosophy and the human sciences can be placed on a new footing.", slug: "the-origin-of-language", title: "The Origin of Language", source: "Book" }, { text: "The token issuing institution might then be signing onto the charters issued by the center, committing to issuing a certain line of credit.", slug: "ve-ortexicality-post-axial-age-morality", title: "Ve/ortexicality: Post-Axial Age Morality", source: "Substack" }], sources: [] },
  { term: "Sociality", slug: "sociality", gloss: "Another word for 2nd order Attentionality: The awareness of other social actors allows for \u2018group animals\u2019 [as an evolutionary strategy].", posts: 26, passages: [{ text: "The line between anti-sociality and more formalized sociality is drawn through language itself.", slug: "anthropomorphics-the-center-speaking", title: "The Center, Speaking", source: "Book" }, { text: "Directly representing our sociality is paradoxical, then, because any such representation now becomes the property of our language, requiring new representations.", slug: "anthropomorphics-book", title: "Anthropomorphics: An Originary Grammar of the Center", source: "Book" }, { text: "The complementary problems of succession (the continuity of the center, the system of references of the occupied to the signifying center) and of meaning (enhancing the scenic performativity of our signs), which is all that sociality is comprised of, find their solutions in the creation of such spaces.", slug: "generating-idiomatic-intelligences-and-translation-practices", title: "Generating Idiomatic Intelligences and Translation Practices", source: "Substack" }], sources: [] },
  { term: "Sovereign Imaginary", slug: "sovereign-imaginary", gloss: "Old term for \u2018Central Imaginary\u2019: When one imagines that something should be one way or another, you\u2019re also imagining a sovereign who can carry it out and make it so.", posts: 10, passages: [{ text: "A sovereign imaginary implies a staffing of the officer class.", slug: "on-the-use-of-the-center-margin-model-to-displace-the-left-right-model", title: "On the Use of the Center-Margin Model to Displace the Left-Right Model", source: "GABlog" }, { text: "To the liberal presupposing an anarchist sovereign imaginary we counter-presuppose sovereign naming.", slug: "semiotic-engineering-gablog", title: "Semiotic Engineering", source: "GABlog" }, { text: "Even a globalist, even an anarchist, inhabits a sovereign imaginary, whether it be international human rights courts and organizations mediating trade disputes, on the one hand, or spontaneously formed agreements between unbound individuals, on the other hand.", slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }], sources: [{ slug: "the-central-imaginary-gablog", title: "The Central Imaginary", source: "GABlog" }] },
  { term: "Sovereignty", slug: "sovereignty", concept: "sovereignty", gloss: "To command attention in a way that increases the extent to which those participating within a scene uptake responsibility, relative to the embeddedness of said participants (within late-culture this would possibly manife.", posts: 197, passages: [{ text: "Sovereignty is the defense of the line qualifying the actors and audience.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }, { text: "Sovereignty is the central issue here, more explicitly than it has ever been.", slug: "saturating-sovereignty", title: "Saturating Sovereignty", source: "GABlog" }, { text: "Sovereignty is always passed off\u2014to be sovereign is to decide upon one\u2019s successor.", slug: "securing-sovereignty", title: "Securing Sovereignty", source: "GABlog" }], sources: [{ slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }, { slug: "the-bearer-of-sovereignty", title: "The Bearer of Sovereignty", source: "Substack" }] },
  { term: "Sparagmos", slug: "sparagmos", concept: "sparagmos", gloss: "Dividing the central object in the Originary Event which serves as the source of defilement, or originary mistakenness.", posts: 32, passages: [{ text: "In this case, the participants in the sparagmos are essentially summarizing the scene to each other.", slug: "language-inquiry", title: "Language, Inquiry", source: "GABlog" }, { text: "So it\u2019s delayed\u2014but if the sparagmos is, in fact the central being giving itself up, wouldn\u2019t that \u201cappease\u201d rather than exacerbate any resentment?", slug: "hunger-artistry-of-the-word", title: "Hunger Artistry of the Word", source: "GABlog" }, { text: "Subsequent to the sparagmos is a repetition or replay of the originary scene making use of the remains of the devoured object\u2014this is the origin of ritual.", slug: "the-generativity-of-deferral", title: "The Generativity of Deferral", source: "GABlog" }], sources: [{ slug: "ap1601-1601katz", title: "Originary Mistakenness, Defilement and Modernity", source: "AP Journal" }], },
  { term: "Teaching", slug: "teaching", gloss: "Seeing an Ostensive in play.", posts: 59, passages: [{ text: "Teaching is always a gift to a stranger, even if the teacher and student are close friends, because we are meeting on a yet to be generated scene of joint attention, and on that scene we will become different from what we are.", slug: "economism", title: "Economism", source: "GABlog" }, { text: "To think technologically about teaching is to think in terms of the various ways of \"downloading\" models.", slug: "double-helix-v9-teaching-machines-review", title: "Book Review: Teaching Machines \u2014 Audrey Watters (Adam Katz)", source: "Essay" }, { text: "In this case, I\u2019m also learning (a teacher who doesn\u2019t learn things in teaching is a bad teacher).", slug: "nominalization-imperativity-and-reading-quick-or-patient", title: "Nominalization, Imperativity and Reading, Quick or Patient", source: "GABlog" }], sources: [{ slug: "mimeticism-and-morality", title: "Mimeticism and Morality", source: "GABlog" }, { slug: "sovereign-as-onomastician-in-chief", title: "Sovereign as Onomastician-in-Chief", source: "GABlog" }] },
  { term: "Technics", slug: "technics", concept: "technology", gloss: "The scenic design component of the constitution of the human: Technics is about making Imperatives that are attached to a particular model conform to that model without deviation.", posts: 35, passages: [{ text: "Technics is the continual reinscription of the scene\u2014scenic design practices are events within scenes that design scenes in ways that facilitate new events.", slug: "event-intelligence", title: "Event Intelligence", source: "Substack" }, { text: "How do we solve problems, especially technical problems\u2014but that means all problems, because technics is nothing more than the construction, maintenance, and modification of the scenes upon which we act.", slug: "figuring-things-out", title: "Figuring Things Out", source: "Substack" }, { text: "Technics, that is, serves the originary media of the scene\u2014everyone positioned in a particular way in relation to the center so as to re-enact the originary scene.", slug: "mimological-impressments", title: "Mimological Impressments", source: "Substack" }], sources: [{ slug: "mimological-impressments", title: "Mimological Impressments", source: "Substack" }, { slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "Technology", slug: "technology", concept: "technology", gloss: "The creation of expanded scenes enhancing unidirectional center-periphery communication.", posts: 158, passages: [{ text: "Technology is imperative\u2014what we become capable of doing becomes what we have no choice but to do.", slug: "back-to-nature", title: "Back to Nature", source: "GABlog" }, { text: "Technology is completely bound up with the specific forms the centralization of power takes in the wake of the desacralization of power.", slug: "the-event-of-technology-gablog", title: "The Event of Technology", source: "GABlog" }, { text: "Technology is at least potentially solid and enduring\u2014we can tell how long built things will last\u2014but finance is exactly the opposite.", slug: "credit-idiom-imperative-perfection-expectant-scenes", title: "Credit-Idiom-Imperative Perfection: Expectant Scenes", source: "Substack" }], sources: [{ slug: "originary-grammar-as-model-for-scenic-design-intelligence", title: "Originary Grammar as Model for Scenic Design Intelligence", source: "Substack" }] },
  { term: "The Big Scene", slug: "the-big-scene", gloss: "The scene where everyone is imagined to have already signed appropriately regardless of the immanent reality of whether they really have or not.", posts: 15, passages: [{ text: "The Big Scene is big in size and in consequences, but most importantly it is big in the sense of limitless because it is a scene constructed, not around a center, but in order to prevent the emergence of a center.", slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }, { text: "I\u2019ll be coming back here to issues addressed in a post from April 9, 2019, \u201cThe Big Scene is the Anthropological Basis of Anarchist Ontology,\u201d and which I can now place in the context of the conversion of the ritual/mythical nexus into practices.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "On the Big Scene we will never be done with money, capital, debt, exemplary victims and the apocalyptic struggle against tyranny.", slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }], sources: [{ slug: "the-big-scene-is-the-anthropological-basis-of-anarchist-ontology-gablog", title: "The Big Scene is the Anthropological Basis of Anarchist Ontology", source: "GABlog" }, { slug: "mistakenness-revisited-gablog", title: "Mistakenness Revisited", source: "GABlog" }, { slug: "scenic-design-practices-the-transfer-translation-of-events-into-scenes", title: "Scenic Design Practices: The Transfer Translation of Events into Scenes", source: "Substack" }] },
  { term: "The West", slug: "the-west", gloss: "Commitment to the Disciplines.", posts: 80, passages: [{ text: "The West is the inheritor of the Big Man revolution\u2014as for why this should be the case, well, here we can welcome all those intellectual, political and even genetic genealogies of the West.", slug: "rotating-dictatorship", title: "Rotating Dictatorship", source: "Substack" }, { text: "Perhaps the main export of the West is our music, movies, and television shows.", slug: "towards-a-globalist-victimary-unified-field-theory", title: "Towards a Globalist-Victimary Unified Field Theory", source: "GABlog" }, { text: "To a great extent the pre-modern history of the West is a series of attempts to make sense of the sovereign\u2019s accountability to God.", slug: "the-attentional-structure-of-sovereignty", title: "The Attentional Structure of Sovereignty", source: "GABlog" }], sources: [] },
  { term: "Thinking", slug: "thinking", gloss: "The construction and arranging of formal objects within an abstracted mental-space.", posts: 522, passages: [{ text: "A model of thinking is always a model of a disciplinary space.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }, { text: "I don\u2019t deny that originary thinking is also compatible with liberalism, just that it only and intrinsically is so.", slug: "the-originary-hypothesis-and-reactionary-thinking", title: "The Originary Hypothesis and Reactionary Thinking", source: "GABlog" }, { text: "The problem of political thinking is to scale up the self-discipline we practice so as to exercise sovereignty where we can.", slug: "anthropomorphics-and-reaction", title: "Anthropomorphics and Reaction", source: "GABlog" }], sources: [{ slug: "ap1302-1302gans", title: "Generative Anthropology \u2013 A New Way of Thinking?", source: "AP Journal" }] },
  { term: "Thirdness", slug: "thirdness", gloss: "Those who gather around an already-active disciplinary space and its initiated first and second members.", posts: 22, passages: [{ text: "Thirdness is the recipient and normalization of the interplay of firstness and secondness, founding and institutionalization, but it is also the position of the witness or spectator.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }, { text: "Thirdness is intended to be such a mode of organizing and strategizing.", slug: "the-tokenization-of-resentment", title: "The Tokenization of Resentment", source: "Substack" }, { text: "Thirdness is to be designed so as simulate this process of transformation so closely as to eventually become it.", slug: "modeling-thirdness-2", title: "Modeling Thirdness 2", source: "Substack" }], sources: [{ slug: "mimetic-theory-and-high-low-v-the-middle", title: "Mimetic Theory and High-Low v the Middle", source: "GABlog" }] },
  { term: "Threshold of Significance", slug: "threshold-of-significance", gloss: "The \u2018amount\u2019 of meaning that a Sign possess.", posts: 26, passages: [{ text: "I think we could say that lowering the threshold of significance is the way we conserve linguistic presence: what threatens linguistic presence is the loss of a shared center that we could point to; by lowering the threshold of significance we place a newly identified object at that center.", slug: "cognition-as-originary-memory", title: "Cognition as Originary Memory", source: "GABlog" }, { text: "All practices tend towards lowering the threshold of significance.", slug: "transposing-the-scene", title: "Transposing the Scene", source: "GABlog" }, { text: "This means inventing practices that lower the threshold of significance.", slug: "the-single-source-of-moral-and-intellectual-innovation-gablog", title: "The Single Source of Moral and Intellectual Innovation", source: "GABlog" }], sources: [] },
  { term: "Truth", slug: "truth", gloss: "Meaningful content by virtue of being communally significant.", posts: 181, passages: [{ text: "The truth is, you can\u2019t argue about abuses of the civil rights legal and political inheritance without being forced to disentangle what from that inheritance is worthy of preservation.", slug: "fighting-pc", title: "Fighting PC", source: "GABlog" }, { text: "The truth is that, strictly speaking, desire cannot coincide with meaning: the purer the desire, the more any interference with that desire must be destroyed, intellectually and physically, if possible.", slug: "the-grammar-of-desire-and-resentment", title: "The Grammar of Desire and Resentment", source: "GABlog" }, { text: "The truth is that the anti-white dimension of the globalist/leftist juggernaut goes far deeper than any \u201cwelfare state,\u201d \u201cregulatory,\u201d or \u201cmeritocratic\u201d issues can get at, and requires for its intellectual dismantling a more sophisticated hermeneutics that relies upon in-group tacit agreement.", slug: "the-prospects-of-sovereignty", title: "The Prospects of Sovereignty", source: "GABlog" }], sources: [{ slug: "truth", title: "Truth", source: "GABlog" }, { slug: "absolutist-epistemology", title: "Absolutist Epistemology", source: "GABlog" }, { slug: "truth-and-practice", title: "Truth and Practice", source: "GABlog" }] },
  { term: "Tyranny", slug: "tyranny", gloss: "Violating the moral history of a group: When a leader violates the moral history of a group, it gives rise to the feeling of tyranny, and the leader being a tyrant.", posts: 60, passages: [{ text: "Tyranny is the manifestation of and response to greed and the desire for domination, \u201cpassions\u201d liberated on the post-sacral market.", slug: "anthropomorphics-metalanguage-and-metapolitics", title: "Metalanguage and Metapolitics", source: "Book" }, { text: "This is the only way to fully recoup the Big Man revolution (against the Left, which is really primarily, ferociously, primordially, opposed to precisely this) and \u201csolve\u201d the problem of tyranny is through the establishment of a rotating dictator system.", slug: "rotating-dictatorship", title: "Rotating Dictatorship", source: "Substack" }, { text: "Politics can be distinguished from rule, or tyranny, by the competitive nature of the struggle and the actor-audience relation.", slug: "the-problem-and-possible-necessity-of-politics", title: "The Problem and Possible Necessity of Politics", source: "GABlog" }], sources: [] },
  { term: "Universalism", slug: "universalism", gloss: "The fantasy that all humans are occupying the same Disciplinary Space.", posts: 11, passages: [{ text: "Universalism is the fantasy that all humans are occupying the same disciplinary space.", slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }, { text: "Universalism is really the imagining of the world under a single empire\u2014not necessarily under the rule of a single individual or institution (but maybe that as well), but certainly all subject to the same regime of rights and their enforcement.", slug: "nationalism-globalism-empire", title: "Nationalism, Globalism, Empire", source: "GABlog" }, { text: "In universalism, the individual is imagined as potential victim of overweening power, and the solution is for that individual to be ever further abstracted so as to be acted upon by an even overweenier power.", slug: "absolutism-the-axial-age-and-the-laboratory", title: "Absolutism, the Axial Age and the Laboratory", source: "GABlog" }], sources: [{ slug: "formalism-all-the-way-down-gablog", title: "Formalism all the way down", source: "GABlog" }] },
  { term: "Victimary Thinking", slug: "victimary-thinking", concept: "resentment-victimary", gloss: "The postmodern tendency to take the moral model of reciprocity, and equality before the Sign as language users, to an extreme that denies Firstness, allowing Usurpation of the Center by the Periphery: As a tendency trace.", posts: 38, passages: [{ text: "Victimary thinking is, most fundamentally, resentment towards civilization\u2014a resentment only possible for the civilized, or those in close proximity to them.", slug: "the-offspring-of-the-progenitor-of-lies", title: "The Offspring of the Progenitor of Lies", source: "GABlog" }, { text: "Victimary thinking is an ugly and dangerous business, but the inhabitants of advanced economies in their \u201ccrowd-sourced\u201d wisdom appear to have determined so far that it is the lesser evil compared to naked hierarchy.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }, { text: "Victimary thinking is, for Gans, a moral transformation in Western society resulting from the shock at the Nazi genocide of the Jews.", slug: "the-anthropoetics-of-power", title: "The Anthropoetics of Power", source: "Essay" }], sources: [{ slug: "clr-230", title: "Victimary Thinking Forever?", source: "Chronicles" }, { slug: "clr-538", title: "Victimary Passion", source: "Chronicles" }, { slug: "clr-499", title: "Firstness and Victimary Religion", source: "Chronicles" }] },
  { term: "Wisdom", slug: "wisdom", gloss: "Restoration of attention back to the Center.", posts: 42, passages: [{ text: "Wisdom, we can say, is the bringing to bear of the paradoxical nature of human existence as a means of deferral of sacrifice.", slug: "the-center-its-affordances-and-issuances-and-time", title: "The Center, its Affordances and Issuances, and Time.", source: "Substack" }, { text: "The new urbanity might be historical wisdom, and it might provide a model for leaving off defense of civilized standards.", slug: "the-rhythm-of-civilization", title: "The Rhythm of Civilization", source: "GABlog" }, { text: "We have the \u201ccrowd-sourced\u201d wisdom of the inhabitants, but then the \u201ctransnational elite\u201d and its hierarchy makes an immediate entrance.", slug: "im-morality-and-in-equality-gablog", title: "(Im)morality and (In)equality", source: "GABlog" }], sources: [] },
];
